INSERT INTO "collectible_token_types" ("id", "token_id", "category", "name", "description", "chain_id", "contract_address", "metadata_cid", "max_supply", "minted_supply", "per_wallet_limit", "mint_start", "mint_end", "transferable", "metadata_frozen", "active", "source_type", "source_id", "status", "created_at", "updated_at") VALUES ('33a4321d-db8f-402b-b721-dc12beee1dd8', 8, 'CONCERT_CARD', 'FEAR and DREAMS 纪念票', '由 Fanora 为完成 FEAR and DREAMS 粉丝记忆任务的成员发行的限量 ERC-1155 演唱会纪念票。', 10143, '0xb2ffc47d5a9407f0118e12749847821530533a84', 'bafkreigbqejfky6bx34wqfpercrizi6fkxb7qonkdyz5d5avzt6ki4vahu', 10000, 4, 1, '2026-07-23T05:43:57.637567+00:00', '2036-07-20T05:44:57.637567+00:00', FALSE, FALSE, TRUE, 'TASK_REWARD', '00000000-0000-0000-0000-000000000020', 'CONFIRMED', '2026-07-23T05:44:57.637874+00:00', '2026-07-23T05:44:57.637884+00:00');
INSERT INTO "collectible_token_types" ("id", "token_id", "category", "name", "description", "chain_id", "contract_address", "metadata_cid", "max_supply", "minted_supply", "per_wallet_limit", "mint_start", "mint_end", "transferable", "metadata_frozen", "active", "source_type", "source_id", "status", "created_at", "updated_at") VALUES ('d3c65b42-29fb-4d7e-9b61-1c5c8a2b4919', 2448929907847408979, 'FAN_LIMITED_NFT', '安可绽放时', '这是一枚凝固了演唱会最高潮瞬间的数字纪念票根。作品以横向悬浮的 3D 纸质票根为载体，左侧主画面将粉丝记忆中的镜像侧脸转化为温柔细腻的手绘插画：两抹背对背的剪影在舞台暖金逆光中静默伫立，象征着时间与自我的深情对话。缤纷的彩带如记忆碎片般在周身飞舞，与底部隐约的人群剪影交织，重现现场的热烈与感动。右侧保留经典的半圆缺口与虚线打孔副券，整体采用清新明亮的 pastel 色调与柔和投影，既是对那场梦境的温柔复刻，也是专属粉丝的情感资产，适合永久珍藏于数字钱包或作为社群身份徽章。', 10143, '0xb2ffc47d5a9407f0118e12749847821530533a84', 'bafkreibh7s2gvwmnqfre6pojp3qgytkf2n4badcqqfc6uguin3wbyoe3hi', 100, 1, 100, '2026-08-02T12:09:37.210691+00:00', '2036-07-30T12:10:37.210691+00:00', TRUE, FALSE, TRUE, 'FAN_NFT', '99abd959-53a5-4996-8306-c2da3aba3da4', 'CONFIRMED', '2026-08-02T12:10:37.210869+00:00', '2026-08-02T12:10:37.210882+00:00');
INSERT INTO "collectible_token_types" ("id", "token_id", "category", "name", "description", "chain_id", "contract_address", "metadata_cid", "max_supply", "minted_supply", "per_wallet_limit", "mint_start", "mint_end", "transferable", "metadata_frozen", "active", "source_type", "source_id", "status", "created_at", "updated_at") VALUES ('7052c6fd-2da6-4fb6-ac03-04e624b59ac7', 2243342390542346829, 'FAN_LIMITED_NFT', '大头仔', '大头仔', 10143, '0xb2ffc47d5a9407f0118e12749847821530533a84', 'bafkreifvm2u4ohq2c7yedyigfblkkkvhlanqeit4ncelg3betbbtlwkwqy', 10, 2, 10, '2026-07-24T08:03:06.065681+00:00', '2036-07-21T08:04:06.065681+00:00', TRUE, FALSE, TRUE, 'FAN_NFT', '9abc8a71-6cd5-4bf9-b634-7a1bfe64f31d', 'CONFIRMED', '2026-07-24T08:04:06.065822+00:00', '2026-07-24T08:04:06.065832+00:00');
