INSERT INTO "collectible_token_types" ("id", "token_id", "category", "name", "description", "chain_id", "contract_address", "metadata_cid", "max_supply", "minted_supply", "per_wallet_limit", "mint_start", "mint_end", "transferable", "metadata_frozen", "active", "source_type", "source_id", "status", "created_at", "updated_at") VALUES ('de062b55-909f-4005-a3bb-7c162e2d0ac5', 3185198114609747535, 'FAN_LIMITED_NFT', '粉圆·思绪漫游', '一枚粉色圆形徽章，以极简的黑色线条勾勒出闭目沉思的抽象面孔。周围环绕的波浪线条仿佛具象化的思绪或声波，在静谧中传递着内心的独白。', 10143, '0xb2ffc47d5a9407f0118e12749847821530533a84', 'bafkreihcvjrim62mz5bv7irxe35fyuxrwbcqkluafjtzthacesvbcmnwfu', 100, 1, 100, '2026-08-02T09:48:59.344828+00:00', '2036-07-30T09:49:59.344828+00:00', TRUE, FALSE, TRUE, 'FAN_NFT', 'a9ccd45a-2e70-4c1e-82e0-dd21a5953d15', 'CONFIRMED', '2026-08-02T09:49:59.345393+00:00', '2026-08-02T09:49:59.345400+00:00');
INSERT INTO "collectible_token_types" ("id", "token_id", "category", "name", "description", "chain_id", "contract_address", "metadata_cid", "max_supply", "minted_supply", "per_wallet_limit", "mint_start", "mint_end", "transferable", "metadata_frozen", "active", "source_type", "source_id", "status", "created_at", "updated_at") VALUES ('9753e175-e9c6-4cb3-a056-43d9afe46608', 3569097882092117569, 'FAN_LIMITED_NFT', '大头仔', '大头仔', 10143, '0xb2ffc47d5a9407f0118e12749847821530533a84', 'bafkreia4hz3zlyoo6fsjwoxyyovftmx427hhp3sdcbi62mvrqm7yhhj3jq', 10, 3, 10, '2026-07-24T08:04:49.785344+00:00', '2036-07-21T08:05:49.785344+00:00', TRUE, FALSE, TRUE, 'FAN_NFT', 'a2c616b0-94dc-4b7c-ae6a-6b4cfbf28e24', 'CONFIRMED', '2026-07-24T08:05:49.785449+00:00', '2026-07-24T08:05:49.785457+00:00');
INSERT INTO "collectible_token_types" ("id", "token_id", "category", "name", "description", "chain_id", "contract_address", "metadata_cid", "max_supply", "minted_supply", "per_wallet_limit", "mint_start", "mint_end", "transferable", "metadata_frozen", "active", "source_type", "source_id", "status", "created_at", "updated_at") VALUES ('56ef9e83-1949-434a-9d20-781ee1e82c1e', 1958481222723263807, 'FAN_LIMITED_NFT', '写给这份喜欢的喜欢', '这份 NFT 记录的是：用户基于陈奕迅的视觉模板发起创作，提取了“成熟克制、略带疲惫、幽默内敛”的气质特征，以及“西装革履却略显忙乱、佩戴耳机”的视觉元素。创作核心从单纯的艺人肖像转化为一种普世的粉丝情感投射：在繁忙的成人世界（西装、便签、歪斜领带）中，依然通过音乐（耳机）守护内心秩序的普通人形象。视觉风格选定为 Chibi，旨在用柔和可爱的形式消解现实的沉重，强调“陪伴”与“自我和解”的情感价值。。它不补写未发生的演出、现场或共同经历，只保留粉丝亲自表达的欣赏与情绪。## 小标题', 10143, '0xb2ffc47d5a9407f0118e12749847821530533a84', 'bafkreifntcznnbukpfkp7v7ltlk423xci7r62jee4ax5stoqja2k4snkiq', 100, 1, 100, '2026-08-02T12:22:04.959049+00:00', '2036-07-30T12:23:04.959049+00:00', TRUE, FALSE, TRUE, 'FAN_NFT', '94c11f0e-3df0-4e40-b9e4-218f15de72f4', 'CONFIRMED', '2026-08-02T12:23:04.959393+00:00', '2026-08-02T12:23:04.959409+00:00');
INSERT INTO "collectible_token_types" ("id", "token_id", "category", "name", "description", "chain_id", "contract_address", "metadata_cid", "max_supply", "minted_supply", "per_wallet_limit", "mint_start", "mint_end", "transferable", "metadata_frozen", "active", "source_type", "source_id", "status", "created_at", "updated_at") VALUES ('cb003d0d-c8fd-41fb-83cf-23bacdff1f05', 856591310618614889, 'FAN_LIMITED_NFT', '霓虹情绪圆脸', '本作以手绘涂鸦为核心语言，将粉丝群体在音乐共鸣中瞬息万变的情绪具象化为数十个色彩斑斓的圆形面孔。作品摒弃具象场景，转而通过随性不完美的黑色线条与高饱和霓虹色块的层叠交错，构建出一种独立音乐周边的独特质感。Risograph 印刷特有的错位纹理与纸张颗粒感，赋予了数字藏品实体收藏的温度，寓意每一位听众都是这团黑色背景中不可或缺的独特光点，共同组成了这场永不散场的内心狂欢。', 10143, '0xb2ffc47d5a9407f0118e12749847821530533a84', 'bafkreihpzvnlxwdbjxvq25d54zailnzffkjdpbh3db5jhqzs7jcukfgtnm', 50, 1, 50, '2026-08-02T12:26:21.387337+00:00', '2036-07-30T12:27:21.387337+00:00', TRUE, FALSE, TRUE, 'FAN_NFT', '2707299e-36aa-4966-8f8f-25c91ed00bad', 'CONFIRMED', '2026-08-02T12:27:21.387561+00:00', '2026-08-02T12:27:21.387573+00:00');
INSERT INTO "collectible_token_types" ("id", "token_id", "category", "name", "description", "chain_id", "contract_address", "metadata_cid", "max_supply", "minted_supply", "per_wallet_limit", "mint_start", "mint_end", "transferable", "metadata_frozen", "active", "source_type", "source_id", "status", "created_at", "updated_at") VALUES ('6a338765-af95-4c14-9f07-efc5f820b653', 1650922712272353889, 'FAN_LIMITED_NFT', '尘心自洽', '作品源自一段正在形成的真实粉丝记忆，以“尘大师”的意象隐喻自我和解的宁静时刻。画面重构为 8-bit 像素艺术风格，将原本手绘的冥想者转化为复古游戏中的治愈系角色。背景保留了旧牛皮纸的温暖棕色调与纤维质感，但通过像素网格重新诠释，营造出数字怀旧与手工温度交织的独特氛围。中央人物盘腿而坐，闭目微笑，夸张的卷发与简约衣着以明亮的色块呈现，既保留了原作的稚拙幽默，又增添了电子收藏品的趣味性与稀缺感。这不仅是一张专辑封面的数字变体，更是一枚象征内心平静与日常陪伴的像素徽章，记录着粉丝在音乐中找到共鸣的纯粹瞬间。', 10143, '0xb2ffc47d5a9407f0118e12749847821530533a84', 'bafkreifrlkscptk2yics54r4h5hndv75nae5iccjv7jz5gt33fmv62ytry', 500, 1, 500, '2026-08-02T13:39:51.946151+00:00', '2036-07-30T13:40:51.946151+00:00', TRUE, FALSE, TRUE, 'FAN_NFT', '3ced625b-46ed-4968-80d1-2509afd65edd', 'CONFIRMED', '2026-08-02T13:40:51.946200+00:00', '2026-08-02T13:40:51.946204+00:00');

