INSERT INTO "fan_profile_runs" ("id", "user_id", "wallet_address", "community_id", "input_payload", "output_payload", "analysis_source", "created_at", "rule_version", "prompt_version", "model_id", "degraded") VALUES ('10bd53ff-32eb-4e46-add1-0afa90350141', '705c9595-ecc7-44cd-82fd-b3e6be27dd65', '0x5f2984012287D703a9a42e15BBd50D1B1CE9427b', 'global', '{"fan_token_balance":19311,"completed_tasks":5,"active_days":5,"referrals":0,"onchain_actions":20,"chain_summary":{"confirmed_collectibles":6,"confirmed_operations":20,"early_supporter":false},"risk_signals":[]}', '{"run_id":"3c02e91a-267a-4e9b-9900-ffacbf388643","wallet_address":"0x5f2984012287D703a9a42e15BBd50D1B1CE9427b","scores":{"activity":50,"loyalty":100,"influence":60,"contribution":100,"total":79},"fan_type":"emerging_fan","labels":["emerging_fan"],"risk_level":"low","summary":"This wallet is classified as emerging_fan with a total score of 79/100 based on verified Fanora activity.","analysis_source":"rules","badge_eligible":true,"badge_draft":{"name":"Emerging Fan Badge","description":"Proof of Fandom badge draft generated from verified Fanora activity.","level":"emerging_fan","image_prompt":"A premium Fanora digital commemorative badge with musical energy and verifiable fandom symbolism.","suggested_attributes":[{"trait_type":"Fan Type","value":"emerging_fan"},{"trait_type":"Score","value":"79"}]},"recommended_tasks":[]}', 'rules', '2026-07-31T02:34:22.067643+00:00', 'fan-profile-v3', 'fan-profile-prompt-v3', 'rules', TRUE);

