INSERT INTO "nft_forge_sessions" ("id", "user_id", "conversation_id", "template_id", "visual_style", "title", "story_summary", "image_prompt", "reference_image_urls", "suggested_attributes", "supply", "price_fan_tokens", "forge_mode", "status", "rules_version", "generated_versions", "selected_version_id", "published_at", "created_at", "updated_at") VALUES ('8977da0f-a660-4a33-a88f-3774e75e79e7', '705c9595-ecc7-44cd-82fd-b3e6be27dd65', '4722f589da704f11aae177db995aa3ac', 'ab1fd158-979a-4ec1-8c55-7394d15406e5', 'cinematic', '惊悸回响', '作品名为''Fear''，源于舞台幕布后那道未知的注视。故事捕捉了演出前或落幕时，观众或表演者感知到幕布阴影中潜伏目光的瞬间。视觉上，厚重的天鹅绒幕布占据前景，细微的缝隙透出舞台内部的冷光，勾勒出后方模糊却令人不安的轮廓。整体氛围压抑而神秘，通过光影的强烈反差表现内心对未知的恐惧，将瞬间的心理惊悚凝固为可收藏的数字 artifact。', 'A premium collectible NFT card design featuring heavy crimson velvet stage curtains in the immediate foreground with a tactile fabric texture. A narrow vertical gap reveals a cold, eerie blue spotlight from behind, silhouetting a vague, unsettling humanoid shape in the deep background. Cinematic stage lighting with high contrast chiaroscuro, volumetric fog beams cutting through the darkness. The composition is framed as a high-end trading card or enamel pin mockup with a subtle metallic border, macro photography style, shallow depth of field focusing on the curtain texture and the glowing gap. Atmosphere is oppressive, mysterious, and psychologically thrilling. 8k resolution, octane render, unreal engine 5, hyper-realistic material details.', '["https://gateway.pinata.cloud/ipfs/bafybeihgkfsd7ym5fzced66nuhgzjgys4rn4zo25wprmijqtq4h4rbp6lm"]', '[{"trait_type":"Emotion","value":"Uncanny Dread"},{"trait_type":"Lighting","value":"Cold Stage Blue"},{"trait_type":"Material","value":"Velvet & Shadow"},{"trait_type":"Rarity","value":"Behind the Curtain"},{"trait_type":"Format","value":"Digital Artifact"}]', 10, 10, 'FOCUSED', 'ANALYZED', 'forge-v1', '[{"id":"d4745435f845f2af81217dd8","url":"https://bee-mbr-ab.imglnk.cn/v/a09c9d4d29c098dbbe7b19ca51f11470.png","label":"FORGE 1","name":"惊悸回响","description":"本作《惊悸回响》凝固了舞台幕布后那道未知注视的瞬间。厚重的猩红天鹅绒占据前景，细微缝隙中透出的冷冽蓝光，勾勒出后方模糊却令人不安的人形轮廓。作品利用强烈的明暗对照法（Chiaroscuro）与体积光雾，将演出前后那种压抑、神秘且充满心理惊悚的氛围具象化。这不仅是一张数字藏品，更是一枚封存了表演者与观众共同潜意识恐惧的实体化票根，让观者在凝视深渊时，听见内心的回响。","image_prompt":"A premium collectible NFT card design featuring heavy crimson velvet stage curtains in the immediate foreground with hyper-realistic tactile fabric texture and visible weave. A narrow vertical gap reveals a cold, eerie blue spotlight from behind, silhouetting a vague, unsettling humanoid shape in the deep background. Cinematic stage lighting with high contrast chiaroscuro, volumetric fog beams cutting through the darkness. The composition is framed as a high-end trading card or enamel pin mockup with a subtle brushed metallic border, macro photography style, shallow depth of field focusing sharply on the curtain texture and the glowing gap while blurring the background figure. Atmosphere is oppressive, mysterious, and psychologically thrilling. 8k resolution, octane render, unreal engine 5, hyper-realistic material details, no text, no logos.","attributes":[{"trait_type":"Material","value":"Crimson Velvet"},{"trait_type":"Lighting","value":"Cold Blue Spotlight"},{"trait_type":"Mood","value":"Psychological Thriller"},{"trait_type":"Technique","value":"Chiaroscuro"},{"trait_type":"Rarity","value":"Shadow Silhouette"},{"trait_type":"Format","value":"Metallic Edge Card"}]}]', NULL, NULL, '2026-07-31T22:54:09.290328', '2026-07-31T22:57:42.667891');
INSERT INTO "nft_forge_sessions" ("id", "user_id", "conversation_id", "template_id", "visual_style", "title", "story_summary", "image_prompt", "reference_image_urls", "suggested_attributes", "supply", "price_fan_tokens", "forge_mode", "status", "rules_version", "generated_versions", "selected_version_id", "published_at", "created_at", "updated_at") VALUES ('32f33816-3ebc-4f8e-8f0a-2b35730a5088', '705c9595-ecc7-44cd-82fd-b3e6be27dd65', 'c5dcb05d6e63449c93ae3b9b361a6b3e', 'ab1fd158-979a-4ec1-8c55-7394d15406e5', 'cinematic', '写给这份喜欢的喜欢', '用户启动了基于「bigguy 视觉模板」的 NFT 创作，选定「cinematic」电影感风格，并明确要求立即生成图片。当前阶段尚未输入具体的艺人特征、歌曲联想或个人情感故事，因此作品暂时保留模板核心的视觉语言——即厚重的体积感、强烈的明暗对比与实体收藏品的材质表现，作为一个等待被赋予具体灵魂的精神容器。', 'Create a square portrait-free fan collectible about sincere admiration and personal fandom. The story explicitly centers on 这份喜欢. Translate personality, music atmosphere, imagined scenery, daily companionship, or emotional symbolism into an original emblem, environmental vignette, color field, or abstract memorabilia; do not invent a concert, crowd, ticket, performance, stadium, or event not stated in the story. Do not depict a real person''s face, logo, watermark, or readable text.

This is a personal, non-event fan keepsake inspired by personality, music atmosphere, an imagined scene, daily companionship, or an emotional symbol. Depict portrait-free symbolic memorabilia, a stylized environmental scene, a soft color field, or an original mascot-like emblem. It is not a concert or sports event: no stadium, arena, stage, venue, crowd, audience, performance, or live-show lighting.', '["https://gateway.pinata.cloud/ipfs/bafybeihgkfsd7ym5fzced66nuhgzjgys4rn4zo25wprmijqtq4h4rbp6lm"]', '[{"trait_type":"故事主角","value":"这份喜欢"},{"trait_type":"情感","value":"欣赏与喜欢"}]', 5, 10, 'STABLE', 'ANALYZED', 'forge-v1', '[{"id":"a2b674a24e3e1c59514a0667","url":"https://s3.siliconflow.cn/temporary/outputs/2b84p8bu4c0y8_6f794c11efd4198aa58d0189ca8ab413_ComfyUI_3375b956_00001_.png?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Credential=AKIAXXXXFILESEXAMPLE%2F20260802%2Fcn-shanghai-1%2Fs3%2Faws4_request&X-Amz-Date=20260802T051833Z&X-Amz-Expires=86400&X-Amz-SignedHeaders=host&X-Amz-Security-Token=eyJhbGciOiJSUzI1NiIsImtpZCI6ImdyYXkiLCJ0eXAiOiJKV1QifQ..j4KvFFJYjJgWg88WRvQdqyU2S2s6wEaxezD_eoRpkIMHACXn1FpeZjri3KrQG2oe_i6YZeCys4sG2XMSwLp4UAAR35WILr5HUtUmgDOtOE7C2YMpnXxW5WKvZBd819odqM2EYlizOvc8_YI4bJuVm2gMFsT-LqyzHQrnFV4N7OlI5vPxJa1fyN3geNaid1fP4V9XQJ9qVuBrr0f2lxEB1KFqPdywq3Urm1di0jC2FpZdOFZF7kXLo2B5dCNLPe2KIdYIfJ0YMoFchQZ3AGDUuk5ruuVTwspO-EHs2jqwhsqIwK5ca1Y85bNWCmrU414lHlOhdmRFyVvGRKDC9-EfTqhvtUKOLpoM2TeUWN54HbY8--o8nMZqgFDu1rdnJEfQ8BplOrPXdeW0O96etVg32J_lqr-aBNjuddMX4K6shr8hV1b76uQIxUcv5sRDfJzZwdNpHs2ceaR0aiRsAuAKSmEVu5q4SiAOZkRffPEDQwraZXqQFG0D9UoT3JiwAQe6GkJJ4nCe6ywwksOHoFudKSK_up8YI0goKf5na7YPgb0_eEV8FUdtrynJ1rwn0ALhIXIz2d8Dgb9euvkE0qKfQhjJbt_t2pXQtMXAucR2ie0J08Y3bXiuXbtKQpi3vMtVQtRTKYrukGJYO6r0jD-ZkXuBw_xkhKyQsm-O-sfk694&X-Amz-Signature=0dec535a1142901db6437b239bc38ca762f144ce1dbbe0cb5909b6aa89e99d7e","label":"AGENT DRAFT","name":"写给这份喜欢的喜欢","description":"这份 NFT 记录的是：用户启动了基于「bigguy 视觉模板」的 NFT 创作，选定「cinematic」电影感风格，并明确要求立即生成图片。当前阶段尚未输入具体的艺人特征、歌曲联想或个人情感故事，因此作品暂时保留模板核心的视觉语言——即厚重的体积感、强烈的明暗对比与实体收藏品的材质表现，作为一个等待被赋予具体灵魂的精神容器。。它不补写未发生的演出、现场或共同经历，只保留粉丝亲自表达的欣赏与情绪。","image_prompt":"Create a square portrait-free fan collectible about sincere admiration and personal fandom. The story explicitly centers on 这份喜欢. Translate personality, music atmosphere, imagined scenery, daily companionship, or emotional symbolism into an original emblem, environmental vignette, color field, or abstract memorabilia; do not invent a concert, crowd, ticket, performance, stadium, or event not stated in the story. Do not depict a real person''s face, logo, watermark, or readable text.\n\nThis is a personal, non-event fan keepsake inspired by personality, music atmosphere, an imagined scene, daily companionship, or an emotional symbol. Depict portrait-free symbolic memorabilia, a stylized environmental scene, a soft color field, or an original mascot-like emblem. It is not a concert or sports event: no stadium, arena, stage, venue, crowd, audience, performance, or live-show lighting.","attributes":[{"trait_type":"故事主角","value":"这份喜欢"},{"trait_type":"情感","value":"欣赏与喜欢"}]}]', 'a2b674a24e3e1c59514a0667', NULL, '2026-08-02T05:18:38.044734', '2026-08-02T05:19:18.509196');
INSERT INTO "nft_forge_sessions" ("id", "user_id", "conversation_id", "template_id", "visual_style", "title", "story_summary", "image_prompt", "reference_image_urls", "suggested_attributes", "supply", "price_fan_tokens", "forge_mode", "status", "rules_version", "generated_versions", "selected_version_id", "published_at", "created_at", "updated_at") VALUES ('6fc1ea9e-9c35-41c9-b952-c7368b8f7d13', '705c9595-ecc7-44cd-82fd-b3e6be27dd65', '86ceb27377f1434082bedce637d73b82', 'ab1fd158-979a-4ec1-8c55-7394d15406e5', 'photocard', '静默守护', '作品基于「bigguy」视觉模板，定义为一张具有实体收藏质感的 Photocard（闪卡）。叙事核心围绕“沉默而坚定的陪伴力量”，旨在捕捉粉丝在独处时从偶像作品中获得的内心支撑感，而非具体现场回忆。视觉上前中景将呈现一个抽象化的守护者轮廓，背景为深邃的哑光黑，辅以局部烫金工艺勾勒情绪线条。整体氛围庄重、温暖且充满安全感，强调材质本身的触感与光影在卡面上的流动，象征那些未曾说出口却始终存在的应援。', 'A premium square collectible photocard design, macro photography, shallow depth of field. Center subject is an abstract, silhouette-like guardian figure composed of soft, glowing geometric layers, representing silent companionship. Background is deep matte black with subtle grain texture. Foreground features intricate hot-stamped gold foil lines flowing like emotional currents across the surface, catching the light. Material details include high-gloss holographic laminate sheen, iridescent foil accents, and a distinct layered frame structure giving physical depth. Lighting is dramatic yet warm, creating a strong tactile contrast between the velvet-like matte background and the sharp, shiny metallic elements. No text, no logos, no human faces, no watermarks. High-end merchandise packaging aesthetic, 8k resolution, octane render, ray tracing, subsurface scattering on the guardian layers.', '["https://gateway.pinata.cloud/ipfs/bafybeihgkfsd7ym5fzced66nuhgzjgys4rn4zo25wprmijqtq4h4rbp6lm"]', '[{"trait_type":"Rarity","value":"Holographic Guardian"},{"trait_type":"Finish","value":"Matte Black & Hot Gold"},{"trait_type":"Emotion","value":"Silent Companionship"},{"trait_type":"Material","value":"Iridescent Laminate"},{"trait_type":"Series","value":"Bigguy Visual Template"}]', 50, 30, 'FOCUSED', 'ANALYZED', 'forge-v1', '[{"id":"09cb42ec9bd660b507458b89","url":"https://bee-mbr-ab.imglnk.cn/v/cc017ec885eb825ebc6cd56772832846.png","label":"AGENT DRAFT","name":"静默守护","description":"本作定义为一张具有实体收藏质感的 Premium Photocard（闪卡），核心叙事围绕“沉默而坚定的陪伴力量”。画面摒弃具体现场回忆，转而捕捉粉丝在独处时从偶像作品中获得的内心支撑感。视觉上前中景呈现抽象化的守护者轮廓，背景采用深邃哑光黑，辅以局部烫金工艺勾勒情绪线条。整体氛围庄重、温暖且充满安全感，强调材质本身的触感与光影在卡面上的流动，象征那些未曾说出口却始终存在的应援，是粉丝精神世界的具象化信物。","image_prompt":"A premium square collectible photocard design, macro photography, shallow depth of field. Center subject is an abstract, silhouette-like guardian figure composed of soft, glowing geometric layers, representing silent companionship. Background is deep matte black with subtle grain texture. Foreground features intricate hot-stamped gold foil lines flowing like emotional currents across the surface, catching the light. Material details include high-gloss holographic laminate sheen, iridescent foil accents, and a distinct layered frame structure giving physical depth. Lighting is dramatic yet warm, creating a strong tactile contrast between the velvet-like matte background and the sharp, shiny metallic elements. No text, no logos, no human faces, no watermarks. High-end merchandise packaging aesthetic, 8k resolution, octane render, ray tracing, subsurface scattering on the guardian layers.","attributes":[{"trait_type":"Rarity","value":"Holographic Guardian"},{"trait_type":"Finish","value":"Matte Black & Hot Gold"},{"trait_type":"Emotion","value":"Silent Companionship"},{"trait_type":"Material","value":"Iridescent Laminate"},{"trait_type":"Series","value":"Bigguy Visual Template"}]}]', '09cb42ec9bd660b507458b89', NULL, '2026-08-02T06:59:31.212178', '2026-08-02T06:59:31.212201');
