INSERT INTO "nft_forge_sessions" ("id", "user_id", "conversation_id", "template_id", "visual_style", "title", "story_summary", "image_prompt", "reference_image_urls", "suggested_attributes", "supply", "price_fan_tokens", "forge_mode", "status", "rules_version", "generated_versions", "selected_version_id", "published_at", "created_at", "updated_at") VALUES ('c3196b0b-050d-42ce-aa74-5a0cf7961d4c', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', '29fe4810f37e4447a63b84c4869da993', 'ac15fbbb-33e6-461c-ba4e-639aaf1203b6', 'cyber', '赛博声纹', '用户选择「史诗 eason」模板，要求以陈奕迅侧脸剪影为轮廓，内部生长出契合主题的世界观。视觉风格指定为「cyber」（赛博朋克）。核心概念是通过剪影内的赛博场景（如霓虹、机械、数据）与外部柔和水彩质感的冲突融合，表达数字时代中音乐带来的情感连接。目前尚未输入具体的个人故事或特定歌曲意象，系统将默认以‘未来都市中的聆听者’为意象进行首图生成，强调在冷峻科技背景下，音乐剪影所代表的温暖与人性光辉。', 'A square fan collectible artwork featuring a large, distinct silhouette of a male profile facing left as the central container. Inside the silhouette: a hyper-detailed cyberpunk world with glowing neon pipelines, floating data streams, and miniature futuristic architecture, rendered in vibrant pink, purple, and electric blue hues, symbolizing a living digital ecosystem. Outside the silhouette: soft, ethereal watercolor washes in pale warm tones with visible paper grain, dry brush edges, and white space, creating a dreamy atmospheric perspective. The contrast between the sharp, glowing 3D cyber interior and the soft, organic 2D watercolor exterior must be striking yet harmonious. No text, no logos, no watermarks, no realistic human faces. Style: Cinematic double exposure, high-end movie poster aesthetic, surreal narrative synthesis, 8k resolution, intricate details, emotional and sacred atmosphere.

This is a personal, non-event fan keepsake inspired by personality, music atmosphere, an imagined scene, daily companionship, or an emotional symbol. Depict portrait-free symbolic memorabilia, a stylized environmental scene, a soft color field, or an original mascot-like emblem. It is not a concert or sports event: no stadium, arena, stage, venue, crowd, audience, performance, or live-show lighting.', '["https://bee-mbr-ab.imglnk.cn/v/b0b049b18fac1d6ca8417d5121e5d1e1.jpg"]', '[{"trait_type":"Visual Core","value":"Silhouette World-Building"},{"trait_type":"Interior Style","value":"Neon Cyberpunk City"},{"trait_type":"Exterior Texture","value":"Soft Watercolor & Paper Grain"},{"trait_type":"Emotional Tone","value":"Warmth in Cold Tech"},{"trait_type":"Composition","value":"Double Exposure Narrative"},{"trait_type":"Rarity Class","value":"Epic Listener"}]', 1000, 20000, 'FOCUSED', 'ANALYZED', 'forge-v1', '[{"id":"8ef346cdb876f53536c93cb8","url":"https://bee-mbr-ab.imglnk.cn/v/f56d16ad9412109751a08696631a446b.png","label":"AGENT DRAFT","name":"赛博声纹","description":"作品以「赛博声纹」为名，将陈奕迅标志性的侧脸剪影化作通往未来的视窗。轮廓内部并非空洞，而是生长出一座精密运转的赛博都市：霓虹管线如血管般搏动，数据流汇聚成温暖的金色光尘，象征数字时代中音乐所构建的情感连接。剪影外部则采用柔和的水彩晕染与纸张颗粒质感，形成冷峻科技与人性温度的强烈对撞。这枚数字藏品不仅是视觉上的双重曝光，更是一份关于「聆听」的永恒契约——在冰冷的算法世界里，唯有音乐剪影中透出的光辉，能唤醒灵魂深处的共鸣与怀旧诗意。","image_prompt":"A square fan collectible artwork featuring a large, distinct silhouette of a male profile facing left as the central container. Inside the silhouette: a hyper-detailed cyberpunk world with glowing neon pipelines, floating data streams, and miniature futuristic architecture, rendered in vibrant pink, purple, and electric blue hues, symbolizing a living digital ecosystem. Outside the silhouette: soft, ethereal watercolor washes in pale warm tones with visible paper grain, dry brush edges, and white space, creating a dreamy atmospheric perspective. The contrast between the sharp, glowing 3D cyber interior and the soft, organic 2D watercolor exterior must be striking yet harmonious. No text, no logos, no watermarks, no realistic human faces. Style: Cinematic double exposure, high-end movie poster aesthetic, surreal narrative synthesis, 8k resolution, intricate details, emotional and sacred atmosphere.\n\nThis is a personal, non-event fan keepsake inspired by personality, music atmosphere, an imagined scene, daily companionship, or an emotional symbol. Depict portrait-free symbolic memorabilia, a stylized environmental scene, a soft color field, or an original mascot-like emblem. It is not a concert or sports event: no stadium, arena, stage, venue, crowd, audience, performance, or live-show lighting.","attributes":[{"trait_type":"Visual Core","value":"Silhouette World-Building"},{"trait_type":"Interior Style","value":"Neon Cyberpunk City"},{"trait_type":"Exterior Texture","value":"Soft Watercolor & Paper Grain"},{"trait_type":"Emotional Tone","value":"Warmth in Cold Tech"},{"trait_type":"Composition","value":"Double Exposure Narrative"},{"trait_type":"Rarity Class","value":"Epic Listener"}]}]', '8ef346cdb876f53536c93cb8', NULL, '2026-08-02T12:37:35.899884', '2026-08-02T12:41:15.044767');
INSERT INTO "nft_forge_sessions" ("id", "user_id", "conversation_id", "template_id", "visual_style", "title", "story_summary", "image_prompt", "reference_image_urls", "suggested_attributes", "supply", "price_fan_tokens", "forge_mode", "status", "rules_version", "generated_versions", "selected_version_id", "published_at", "created_at", "updated_at") VALUES ('2c8e15dc-4b01-4987-990b-99d4d6b409ac', '705c9595-ecc7-44cd-82fd-b3e6be27dd65', 'c775b43ce1b143eba75c003f418ba230', '86bc45b3-8bd6-4e06-8317-b1ce06a544a9', 'ticket', '深夜契约票根', '用户请求生成图片，但尚未提供具体的个人回忆或特定歌曲关联。基于 Fanora 理念，创作核心暂定为‘无特定现场的日常陪伴’：将听歌时刻视为一场私人的心灵演唱会。视觉载体为一张具有岁月质感的票根，象征粉丝与音乐之间无需言语的长期契约。色彩偏向暖黄与深灰，营造深夜独处的安全感与温暖。', 'A premium digital collectible ticket stub centered in a square composition, featuring a highly textured aged paper surface with visible analog print grain and subtle worn edges. The core visual is an embossed vinyl record-inspired circular element in the center, glowing with a soft warm yellow light against a deep charcoal grey background. Cinematic lighting creates a cozy, intimate atmosphere of late-night solitude. Materials include high-quality cardstock texture, blind embossing, and subtle foil stamping effects without any text or logos. The style is elegant minimal design with macro photography details, shallow depth of field, 8k resolution, conveying emotional safety and silent companionship. No readable text, no human figures, no logos.', '["https://gateway.pinata.cloud/ipfs/bafybeihgkfsd7ym5fzced66nuhgzjgys4rn4zo25wprmijqtq4h4rbp6lm"]', '[{"trait_type":"情感基调","value":"深夜独处"},{"trait_type":"材质质感","value":"岁月再生纸"},{"trait_type":"核心图腾","value":"微光黑胶圆环"},{"trait_type":"色彩氛围","value":"暖黄与深炭灰"},{"trait_type":"收藏意义","value":"心灵契约"},{"trait_type":"工艺风格","value":"模拟印刷颗粒"}]', 100, 20, 'FOCUSED', 'ANALYZED', 'forge-v1', '[{"id":"db0ccfb595dae591ee373f17","url":"https://bee-mbr-ab.imglnk.cn/v/bfdc72f2e80ffe84d76ca73e858e2bb1.png","label":"AGENT DRAFT","name":"深夜契约票根","description":"这是一张象征粉丝与音乐之间无声长期契约的数字票根。作品捕捉了深夜独处时，将听歌时刻转化为私人心灵演唱会的静谧氛围。暖黄色的微光从黑胶纹理的中心溢出，照亮深炭灰色的背景，隐喻在喧嚣世界中寻得的安全感与温暖陪伴。粗糙的再生纸质感与模拟印刷颗粒记录了岁月的痕迹，使其不仅是一件视觉藏品，更是一份关于日常陪伴与内心共鸣的情感档案。","image_prompt":"A premium digital collectible ticket stub centered in a square composition, featuring a highly textured aged paper surface with visible analog print grain and subtle worn edges. The core visual is an embossed vinyl record-inspired circular element in the center, glowing with a soft warm yellow light against a deep charcoal grey background. Cinematic lighting creates a cozy, intimate atmosphere of late-night solitude. Materials include high-quality cardstock texture, blind embossing, and subtle foil stamping effects without any text or logos. The style is elegant minimal design with macro photography details, shallow depth of field, 8k resolution, conveying emotional safety and silent companionship. No readable text, no human figures, no logos.","attributes":[{"trait_type":"情感基调","value":"深夜独处"},{"trait_type":"材质质感","value":"岁月再生纸"},{"trait_type":"核心图腾","value":"微光黑胶圆环"},{"trait_type":"色彩氛围","value":"暖黄与深炭灰"},{"trait_type":"收藏意义","value":"心灵契约"},{"trait_type":"工艺风格","value":"模拟印刷颗粒"}]}]', 'db0ccfb595dae591ee373f17', NULL, '2026-08-02T07:36:32.659232', '2026-08-02T07:36:32.659249');
