INSERT INTO "nft_forge_sessions" ("id", "user_id", "conversation_id", "template_id", "visual_style", "title", "story_summary", "image_prompt", "reference_image_urls", "suggested_attributes", "supply", "price_fan_tokens", "forge_mode", "status", "rules_version", "generated_versions", "selected_version_id", "published_at", "created_at", "updated_at") VALUES ('499e0623-c526-4825-bf2d-d5e9e0739268', '705c9595-ecc7-44cd-82fd-b3e6be27dd65', '07530f3a53724b329109028aceb049bb', 'encore', 'cyber', '回响梦境票根', '用户基于 Fanora 平台创作一件 NFT 数字藏品，核心概念为“双生自我与记忆花园”。画面构图为左右镜像、背对背的两张巨大侧脸肖像（原创人物，非艺人真容），神情平静闭眼，象征回忆与自我对话。两张脸连接处爆发出一座繁盛花园，原本为自然花卉，现随风格更新转化为赛博风格的发光植物或机械花朵。周围漂浮着蝴蝶、飞鸟、记忆碎片及安可彩带（现为光纤或数据流）。背景结合逆光舞台感与赛博空间，人群剪影作为远景衬托。整体旨在表达粉丝在数字时代对音乐记忆的永恒封存，将感性的梦境与理性的科技视觉融合。', 'IMAGE-TO-IMAGE REVISION. The supplied reference image is the source of truth. Preserve its main subject, scene type, camera angle, composition, horizon, focal point, recognizable visual identity, and successful material details unless the user explicitly asks to replace them. Improve the artwork as a coherent NFT or fan-merch collectible rather than changing to an unrelated concept. Apply the latest story and art-direction change: 故事状态已经成熟或用户已明确要求生成。严格实现当前作品状态，参考图是视觉主体的第一优先级，必须保留可识别的主体族群、重复图案、构图密度、线条语言和配色关系；保留主视觉、构图层级、材质、色彩、光线和粉丝收藏品形态；不要改成无关场景，不要加入 Logo、水印、可读文字或未经授权的真实人物肖像。.

Base artwork direction: Hyper-realistic 3D render of a futuristic collectible concert ticket stub held gently between fingers, designed as a transparent thick glass artifact with rounded corners. Inside the glass, a central holographic projection displays two original human profiles in perfect mirror symmetry, facing away from each other with eyes closed in serenity. Bursting from the connection point of their heads is a lush garden of cybernetic flowers, glowing mechanical vines, and neon flora in electric pink, purple, and orange, replacing natural plants. Floating around are fiber-optic encore confetti streams, data-fragment butterflies, and glowing particles. The background within the ticket features a dramatic backlit stage with volumetric lighting and silhouetted crowds in the distance. The ticket edges glow with a gradient of pink, purple, and orange. Materials include clear glossy glass, holograp', '["https://bee-mbr-ab.imglnk.cn/v/bdd55bd25050f6ba3dd692b710c2f426.webp"]', '[{"trait_type":"Collection Type","value":"Holographic Glass Ticket"},{"trait_type":"Visual Theme","value":"Cybernetic Memory Garden"},{"trait_type":"Core Motif","value":"Mirror Self-Portrait"},{"trait_type":"Atmosphere","value":"Backlit Stage & Data Stream"},{"trait_type":"Rarity","value":"Encore Edition"},{"trait_type":"Material Finish","value":"Transparent Neon Glass"}]', 50, 30, 'FOCUSED', 'ANALYZED', 'forge-v1', '[{"id":"f0234ceca49fe1ede6207595","url":"https://bee-mbr-ab.imglnk.cn/v/bbd0a8eea246ea9c96785cf2a5d1c638.png","label":"AGENT DRAFT","name":"回响梦境票根","description":"本作是 Fanora 平台专属的“双生自我与记忆花园”概念纪念票根。画面以左右镜像、背对背的原创人物侧脸为核心，闭目神情象征内在的自我对话与回忆封存。双脸连接处爆发出的不再是自然花卉，而是转化为赛博风格的发光机械植物与数据藤蔓，寓意数字时代下感性梦境与理性科技的融合。周围漂浮的光纤安可彩带、数据流蝴蝶与记忆碎片，在逆光舞台与人群剪影的衬托下，构建出一座永恒的虚拟记忆花园。这不仅是一张入场凭证，更是粉丝将瞬间感动转化为永恒数字资产的信物，完美平衡了史诗感的演唱会氛围与超现实的梦境美学。","image_prompt":"IMAGE-TO-IMAGE REVISION. The supplied reference image is the source of truth. Preserve its main subject, scene type, camera angle, composition, horizon, focal point, recognizable visual identity, and successful material details unless the user explicitly asks to replace them. Improve the artwork as a coherent NFT or fan-merch collectible rather than changing to an unrelated concept. Apply the latest story and art-direction change: 故事状态已经成熟或用户已明确要求生成。严格实现当前作品状态，参考图是视觉主体的第一优先级，必须保留可识别的主体族群、重复图案、构图密度、线条语言和配色关系；保留主视觉、构图层级、材质、色彩、光线和粉丝收藏品形态；不要改成无关场景，不要加入 Logo、水印、可读文字或未经授权的真实人物肖像。.\n\nBase artwork direction: Hyper-realistic 3D render of a futuristic collectible concert ticket stub held gently between fingers, designed as a transparent thick glass artifact with rounded corners. Inside the glass, a central holographic projection displays two original human profiles in perfect mirror symmetry, facing away from each other with eyes closed in serenity. Bursting from the connection point of their heads is a lush garden of cybernetic flowers, glowing mechanical vines, and neon flora in electric pink, purple, and orange, replacing natural plants. Floating around are fiber-optic encore confetti streams, data-fragment butterflies, and glowing particles. The background within the ticket features a dramatic backlit stage with volumetric lighting and silhouetted crowds in the distance. The ticket edges glow with a gradient of pink, purple, and orange. Materials include clear glossy glass, holograp","attributes":[{"trait_type":"Collection Type","value":"Holographic Glass Ticket"},{"trait_type":"Visual Theme","value":"Cybernetic Memory Garden"},{"trait_type":"Core Motif","value":"Mirror Self-Portrait"},{"trait_type":"Atmosphere","value":"Backlit Stage & Data Stream"},{"trait_type":"Rarity","value":"Encore Edition"},{"trait_type":"Material Finish","value":"Transparent Neon Glass"}]}]', 'f0234ceca49fe1ede6207595', NULL, '2026-08-02T08:32:04.173268', '2026-08-02T08:32:04.173287');
INSERT INTO "nft_forge_sessions" ("id", "user_id", "conversation_id", "template_id", "visual_style", "title", "story_summary", "image_prompt", "reference_image_urls", "suggested_attributes", "supply", "price_fan_tokens", "forge_mode", "status", "rules_version", "generated_versions", "selected_version_id", "published_at", "created_at", "updated_at") VALUES ('4f8ebfe4-eb45-43df-95ab-2642c3a21c96', '705c9595-ecc7-44cd-82fd-b3e6be27dd65', NULL, 'encore', 'ticket', '粉圆·思绪漫游', '画面主体为一个粉色圆形背景上的黑色抽象线条人脸，表情平静闭眼。构图居中对称，色彩为高饱和粉色与纯黑对比。材质呈现扁平化矢量图形质感，情绪传达出内省、宁静与自我对话的氛围。', '一张横向的典藏票根卡片设计，左侧区域展示上传的参考图（粉色圆形抽象人脸），将其转化为温柔细腻的手绘插画风格，保留原有的黑色线条和粉色底色，但增加纸张纹理和柔和笔触感，色彩清新明亮。右侧连接一张白色竖向票根标签，边缘带有半圆缺口和虚线打孔效果。整体呈现3D立体纸质票根效果，圆角卡片，具有轻微厚度和柔和投影，悬浮在干净的浅灰色背景上。画面居中构图，留白充足，质感干净，适合小红书分享封面，无真实照片质感，无杂乱背景。', '["https://bee-mbr-ab.imglnk.cn/v/8f2fb8345c5aaccd29789e371ed4e0c3.jpg","https://bee-mbr-ab.imglnk.cn/v/bdd55bd25050f6ba3dd692b710c2f426.webp"]', '[{"trait_type":"主色调","value":"樱花粉"},{"trait_type":"艺术风格","value":"极简线条"},{"trait_type":"情绪状态","value":"内省沉思"},{"trait_type":"视觉元素","value":"抽象人脸"},{"trait_type":"构图形式","value":"圆形徽章"},{"trait_type":"票根类型","value":"典藏纪念"},{"trait_type":"质感","value":"手绘插画"},{"trait_type":"系列","value":"Fanora 情绪图腾"}]', 100, 20, 'FOCUSED', 'PUBLISHED', 'forge-v1', '[{"id":"d0c23be1c8643068cd393288","url":"https://bee-mbr-ab.imglnk.cn/v/8f2fb8345c5aaccd29789e371ed4e0c3.jpg","label":"AGENT DRAFT","name":"粉圆·思绪漫游","description":"一枚粉色圆形徽章，以极简的黑色线条勾勒出闭目沉思的抽象面孔。周围环绕的波浪线条仿佛具象化的思绪或声波，在静谧中传递着内心的独白。","image_prompt":"一张横向的典藏票根卡片设计，左侧区域展示上传的参考图（粉色圆形抽象人脸），将其转化为温柔细腻的手绘插画风格，保留原有的黑色线条和粉色底色，但增加纸张纹理和柔和笔触感，色彩清新明亮。右侧连接一张白色竖向票根标签，边缘带有半圆缺口和虚线打孔效果。整体呈现3D立体纸质票根效果，圆角卡片，具有轻微厚度和柔和投影，悬浮在干净的浅灰色背景上。画面居中构图，留白充足，质感干净，适合小红书分享封面，无真实照片质感，无杂乱背景。","attributes":[{"trait_type":"主色调","value":"樱花粉"},{"trait_type":"艺术风格","value":"极简线条"},{"trait_type":"情绪状态","value":"内省沉思"},{"trait_type":"视觉元素","value":"抽象人脸"},{"trait_type":"构图形式","value":"圆形徽章"},{"trait_type":"票根类型","value":"典藏纪念"},{"trait_type":"质感","value":"手绘插画"},{"trait_type":"系列","value":"Fanora 情绪图腾"}]}]', 'd0c23be1c8643068cd393288', '2026-08-02T09:50:26.668086', '2026-08-02T09:49:07.998746', '2026-08-02T09:50:26.668089');
INSERT INTO "nft_forge_sessions" ("id", "user_id", "conversation_id", "template_id", "visual_style", "title", "story_summary", "image_prompt", "reference_image_urls", "suggested_attributes", "supply", "price_fan_tokens", "forge_mode", "status", "rules_version", "generated_versions", "selected_version_id", "published_at", "created_at", "updated_at") VALUES ('e5790ba7-384d-43f7-94e1-2d0efcd14aab', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', 'a7a9ddf4128741f7aa81dd17a1ddb099', 'encore', 'ticket', '安可绽放时', '用户选择「演唱会纪念票根」视觉模板，要求基于提供的参考图人物，创作一幅超宽幅、超现实梦境风格的演唱会海报。画面核心为两张左右镜像、背对背的侧脸肖像（源自参考图），神情平静闭眼，象征时间与自我对话。人物头部连接处生长出繁盛的梦境花园（玫瑰、牡丹、野花等），伴随蝴蝶、飞鸟、星光与记忆碎片向两侧扩散。背景设定为低饱和灰蓝云层与柔和烟雾，中央辅以逆光和银白光晕，形成黑白人物与鲜艳花朵的冷暖对比。底部预留立体浮雕标题区，顶部预留巡演信息区。整体追求史诗感、艺术摄影质感与精致数字拼贴效果，严禁使用艺人真实肖像或可读文字，仅作为情感资产的视觉隐喻。', 'A high-quality 3D render of a horizontal commemorative concert ticket root floating centrally against a soft, out-of-focus creamy background. The ticket features rounded corners, a tactile premium paper texture with slight thickness, and a perforated vertical stub on the right side with semi-circular notches. The left main panel displays a gentle, detailed hand-drawn illustration style: a pair of mirrored profile silhouettes facing away from each other, bathed in warm golden stage backlight. Colorful confetti ribbons in red, gold, and silver rain down dynamically around the figures, intertwining with faint crowd silhouettes at the bottom. The lighting is cinematic and backlit, creating a glowing halo effect. The color palette is fresh yet warm, combining soft pastels with vibrant confetti colors. No readable text, no logos, no real celebrity faces. The overall mood is nostalgic, celebratory, and dreamlike, suitable for a premium fan collectible or NFT display, octane render, 8k resolution.', '["https://bee-mbr-ab.imglnk.cn/v/bdd55bd25050f6ba3dd692b710c2f426.webp"]', '[{"trait_type":"收藏形态","value":"3D 悬浮票根"},{"trait_type":"视觉风格","value":"温柔手绘插画"},{"trait_type":"核心意象","value":"镜像侧脸与彩带"},{"trait_type":"光影氛围","value":"舞台暖金逆光"},{"trait_type":"情感基调","value":"怀旧庆典"},{"trait_type":"材质质感","value":"细腻纹理纸张"}]', 100, 20, 'FOCUSED', 'PUBLISHED', 'forge-v1', '[{"id":"eb31e58205b4d9cb9f641d0c","url":"https://bee-mbr-ab.imglnk.cn/v/15f060eec3cbe3c9591ee7aab79d4151.png","label":"AGENT DRAFT","name":"安可绽放时","description":"这是一枚凝固了演唱会最高潮瞬间的数字纪念票根。作品以横向悬浮的 3D 纸质票根为载体，左侧主画面将粉丝记忆中的镜像侧脸转化为温柔细腻的手绘插画：两抹背对背的剪影在舞台暖金逆光中静默伫立，象征着时间与自我的深情对话。缤纷的彩带如记忆碎片般在周身飞舞，与底部隐约的人群剪影交织，重现现场的热烈与感动。右侧保留经典的半圆缺口与虚线打孔副券，整体采用清新明亮的 pastel 色调与柔和投影，既是对那场梦境的温柔复刻，也是专属粉丝的情感资产，适合永久珍藏于数字钱包或作为社群身份徽章。","image_prompt":"A high-quality 3D render of a horizontal commemorative concert ticket root floating centrally against a soft, out-of-focus creamy background. The ticket features rounded corners, a tactile premium paper texture with slight thickness, and a perforated vertical stub on the right side with semi-circular notches. The left main panel displays a gentle, detailed hand-drawn illustration style: a pair of mirrored profile silhouettes facing away from each other, bathed in warm golden stage backlight. Colorful confetti ribbons in red, gold, and silver rain down dynamically around the figures, intertwining with faint crowd silhouettes at the bottom. The lighting is cinematic and backlit, creating a glowing halo effect. The color palette is fresh yet warm, combining soft pastels with vibrant confetti colors. No readable text, no logos, no real celebrity faces. The overall mood is nostalgic, celebratory, and dreamlike, suitable for a premium fan collectible or NFT display, octane render, 8k resolution.","attributes":[{"trait_type":"收藏形态","value":"3D 悬浮票根"},{"trait_type":"视觉风格","value":"温柔手绘插画"},{"trait_type":"核心意象","value":"镜像侧脸与彩带"},{"trait_type":"光影氛围","value":"舞台暖金逆光"},{"trait_type":"情感基调","value":"怀旧庆典"},{"trait_type":"材质质感","value":"细腻纹理纸张"}]}]', 'eb31e58205b4d9cb9f641d0c', '2026-08-02T12:10:46.477742', '2026-08-02T12:09:02.252898', '2026-08-02T12:10:46.477748');
INSERT INTO "nft_forge_sessions" ("id", "user_id", "conversation_id", "template_id", "visual_style", "title", "story_summary", "image_prompt", "reference_image_urls", "suggested_attributes", "supply", "price_fan_tokens", "forge_mode", "status", "rules_version", "generated_versions", "selected_version_id", "published_at", "created_at", "updated_at") VALUES ('edbbd798-6384-4540-8b49-8a330c74f5d1', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', 'd733b83350014bcba721f5e5e6002e54', 'f3f1d92b-b2c5-4b78-8edd-024336a3b343', 'chibi', '写给这份喜欢的喜欢', '用户基于陈奕迅的视觉模板发起创作，提取了“成熟克制、略带疲惫、幽默内敛”的气质特征，以及“西装革履却略显忙乱、佩戴耳机”的视觉元素。创作核心从单纯的艺人肖像转化为一种普世的粉丝情感投射：在繁忙的成人世界（西装、便签、歪斜领带）中，依然通过音乐（耳机）守护内心秩序的普通人形象。视觉风格选定为 Chibi，旨在用柔和可爱的形式消解现实的沉重，强调“陪伴”与“自我和解”的情感价值。', 'Create a square portrait-free fan collectible about sincere admiration and personal fandom. The story explicitly centers on 的形式消解. Translate personality, music atmosphere, imagined scenery, daily companionship, or emotional symbolism into an original emblem, environmental vignette, color field, or abstract memorabilia; do not invent a concert, crowd, ticket, performance, stadium, or event not stated in the story. Do not depict a real person''s face, logo, watermark, or readable text.

This is a personal, non-event fan keepsake inspired by personality, music atmosphere, an imagined scene, daily companionship, or an emotional symbol. Depict portrait-free symbolic memorabilia, a stylized environmental scene, a soft color field, or an original mascot-like emblem. It is not a concert or sports event: no stadium, arena, stage, venue, crowd, audience, performance, or live-show lighting.', '["https://bee-mbr-ab.imglnk.cn/v/80ae45426f64eba73cc29cca90491445.jpg"]', '[{"trait_type":"故事主角","value":"的形式消解"},{"trait_type":"情感","value":"欣赏与喜欢"}]', 100, 20, 'FOCUSED', 'PUBLISHED', 'forge-v1', '[{"id":"d4729ae7c3c584dc2fa27bb0","url":"https://bee-mbr-ab.imglnk.cn/v/1222b442fddddbdead26dd2363fc32df.png","label":"AGENT DRAFT","name":"写给这份喜欢的喜欢","description":"这份 NFT 记录的是：用户基于陈奕迅的视觉模板发起创作，提取了“成熟克制、略带疲惫、幽默内敛”的气质特征，以及“西装革履却略显忙乱、佩戴耳机”的视觉元素。创作核心从单纯的艺人肖像转化为一种普世的粉丝情感投射：在繁忙的成人世界（西装、便签、歪斜领带）中，依然通过音乐（耳机）守护内心秩序的普通人形象。视觉风格选定为 Chibi，旨在用柔和可爱的形式消解现实的沉重，强调“陪伴”与“自我和解”的情感价值。。它不补写未发生的演出、现场或共同经历，只保留粉丝亲自表达的欣赏与情绪。","image_prompt":"Create a square portrait-free fan collectible about sincere admiration and personal fandom. The story explicitly centers on 的形式消解. Translate personality, music atmosphere, imagined scenery, daily companionship, or emotional symbolism into an original emblem, environmental vignette, color field, or abstract memorabilia; do not invent a concert, crowd, ticket, performance, stadium, or event not stated in the story. Do not depict a real person''s face, logo, watermark, or readable text.\n\nThis is a personal, non-event fan keepsake inspired by personality, music atmosphere, an imagined scene, daily companionship, or an emotional symbol. Depict portrait-free symbolic memorabilia, a stylized environmental scene, a soft color field, or an original mascot-like emblem. It is not a concert or sports event: no stadium, arena, stage, venue, crowd, audience, performance, or live-show lighting.","attributes":[{"trait_type":"故事主角","value":"的形式消解"},{"trait_type":"情感","value":"欣赏与喜欢"}]}]', 'd4729ae7c3c584dc2fa27bb0', '2026-08-02T12:23:15.417031', '2026-08-02T12:20:06.796258', '2026-08-02T12:23:15.417036');
INSERT INTO "nft_forge_sessions" ("id", "user_id", "conversation_id", "template_id", "visual_style", "title", "story_summary", "image_prompt", "reference_image_urls", "suggested_attributes", "supply", "price_fan_tokens", "forge_mode", "status", "rules_version", "generated_versions", "selected_version_id", "published_at", "created_at", "updated_at") VALUES ('38cef892-d02c-47d8-9906-2aa370087e44', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', '28d5dedf022945429b77268dad2c39a2', 'ab1fd158-979a-4ec1-8c55-7394d15406e5', 'handdrawn', '霓虹情绪圆脸', '用户选择以“周边形象”为视觉核心，采用手绘涂鸦风格（hand-drawn doodle）创作 NFT。作品不依赖具体现场记忆，而是提取粉丝群体共有的情感特质：用数十个色彩鲜艳、线条随性的圆形面孔，表达听歌时丰富多变的内心状态。视觉上使用霓虹色系、重叠构图和 Risograph 印刷纹理，营造独立音乐周边和收藏玩具的质感，黑色背景突显主体的活力与 whimsical 气质，寓意每一位听众都是独特且不可或缺的色彩。', 'A square collectible art piece featuring a dense cluster of dozens of playful hand-drawn doodle mascot characters, specifically colorful circular faces with simple black line expressions and imperfect sketchy outlines. The composition is tightly overlapping, creating a vibrant, chaotic energy against a solid deep black background. The color palette utilizes bright neon hues (cyan, magenta, lime green, electric purple) reminiscent of 8-bit retro games but rendered with a distinct textured Risograph print effect, showcasing slight color misalignment (chromatic aberration) and visible coarse paper grain. The style blends indie music merchandise illustration with Japanese pop graphic design and a whimsical collectible art toy aesthetic. Lighting is flat but high-contrast to emphasize the neon glow without realistic shadows. No text, no logos, no watermarks, no human portraits. High resolution, silkscreen printing texture, energetic and nostalgic atmosphere, suitable for an NFT art toy or limited edition sticker sheet.', '["https://gateway.pinata.cloud/ipfs/bafybeihgkfsd7ym5fzced66nuhgzjgys4rn4zo25wprmijqtq4h4rbp6lm"]', '[{"trait_type":"Visual Style","value":"Hand-drawn Doodle"},{"trait_type":"Texture","value":"Risograph Print"},{"trait_type":"Color Palette","value":"Neon 8-bit"},{"trait_type":"Composition","value":"Dense Overlap"},{"trait_type":"Vibe","value":"Whimsical Energy"},{"trait_type":"Collectible Type","value":"Indie Merch Art"}]', 50, 3000, 'FOCUSED', 'PUBLISHED', 'forge-v1', '[{"id":"989f81c49d6fe436fdb4e830","url":"https://bee-mbr-ab.imglnk.cn/v/8760c04111ee9b328679363431566ae5.png","label":"AGENT DRAFT","name":"霓虹情绪圆脸","description":"本作以手绘涂鸦为核心语言，将粉丝群体在音乐共鸣中瞬息万变的情绪具象化为数十个色彩斑斓的圆形面孔。作品摒弃具象场景，转而通过随性不完美的黑色线条与高饱和霓虹色块的层叠交错，构建出一种独立音乐周边的独特质感。Risograph 印刷特有的错位纹理与纸张颗粒感，赋予了数字藏品实体收藏的温度，寓意每一位听众都是这团黑色背景中不可或缺的独特光点，共同组成了这场永不散场的内心狂欢。","image_prompt":"A square collectible art piece featuring a dense cluster of dozens of playful hand-drawn doodle mascot characters, specifically colorful circular faces with simple black line expressions and imperfect sketchy outlines. The composition is tightly overlapping, creating a vibrant, chaotic energy against a solid deep black background. The color palette utilizes bright neon hues (cyan, magenta, lime green, electric purple) reminiscent of 8-bit retro games but rendered with a distinct textured Risograph print effect, showcasing slight color misalignment (chromatic aberration) and visible coarse paper grain. The style blends indie music merchandise illustration with Japanese pop graphic design and a whimsical collectible art toy aesthetic. Lighting is flat but high-contrast to emphasize the neon glow without realistic shadows. No text, no logos, no watermarks, no human portraits. High resolution, silkscreen printing texture, energetic and nostalgic atmosphere, suitable for an NFT art toy or limited edition sticker sheet.","attributes":[{"trait_type":"Visual Style","value":"Hand-drawn Doodle"},{"trait_type":"Texture","value":"Risograph Print"},{"trait_type":"Color Palette","value":"Neon 8-bit"},{"trait_type":"Composition","value":"Dense Overlap"},{"trait_type":"Vibe","value":"Whimsical Energy"},{"trait_type":"Collectible Type","value":"Indie Merch Art"}]}]', '989f81c49d6fe436fdb4e830', '2026-08-02T12:27:35.906333', '2026-08-02T12:25:20.704466', '2026-08-02T12:27:35.906341');
INSERT INTO "nft_forge_sessions" ("id", "user_id", "conversation_id", "template_id", "visual_style", "title", "story_summary", "image_prompt", "reference_image_urls", "suggested_attributes", "supply", "price_fan_tokens", "forge_mode", "status", "rules_version", "generated_versions", "selected_version_id", "published_at", "created_at", "updated_at") VALUES ('2f64d566-4f8d-4926-bbef-30b58a3996c6', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', 'cf11f5005f374cc7a752357e75f04911', '49a46452-507d-4083-b07d-285e42509b27', 'cyber', '尘大师赛博禅', '用户希望创作一件名为「尘大师」的 NFT 作品，核心概念是在纷扰世界中保持内心的平静与自我和解。画面主体为一位原创男性卡通人物，盘腿冥想，神态温和。虽然用户最初描述了质朴的手绘牛皮纸风格，但在本轮中明确指定将视觉风格调整为「cyber」（赛博朋克）。因此，最终创作方向是将原本的禅意手绘转化为赛博语境：人物依旧保持冥想姿态，但表现形式变为霓虹光感或机械义体风格，背景由旧纸张变为充满科技感的暗调数字空间或全息金属材质，旨在表达“数字修行”或“赛博禅意”的主题，不涉及具体艺人肖像或受版权保护元素。', 'High-quality square NFT collectible card featuring an original male cartoon character in a lotus meditation pose, floating centrally in a dark cyberpunk digital void. The character retains a gentle, peaceful smile with closed eyes, reimagined with glowing neon outlines in cyan and magenta, blending soft organic shapes with translucent mechanical cybernetic limbs and brushed metal textures. The background is a deep, atmospheric tech space with holographic metal surfaces and faint, glowing circuit board patterns, completely replacing any paper texture. Lighting is cinematic and volumetric, with strong rim lighting highlighting the character''s silhouette against the dark environment to evoke ''Cyber Zen''. Style fusion of 3D render and stylized cartoon, using PBR materials like glowing glass and polished chrome. No text, no logos, no watermarks, no readable typography. Composition is centered and balanced, evoking digital tranquility and inner peace amidst chaos. 8k resolution, octane render, ultra-detailed, macro photography aesthetic.

This is a personal, non-event fan keepsake inspired by personality, music atmosphere, an imagined scene, daily companionship, or an emotional symbol. Depict portrait-free symbolic memorabilia, a stylized environmental scene, a soft color field, or an original mascot-like emblem. It is not a concert or sports event: no stadium, arena, stage, venue, crowd, audience, performance, or live-show lighting.', '["https://bee-mbr-ab.imglnk.cn/v/e59f0a24a3df1a6014b28f60279b5624.jpg"]', '[{"trait_type":"Theme","value":"Cyber Zen"},{"trait_type":"Character State","value":"Digital Meditation"},{"trait_type":"Material","value":"Neon & Brushed Metal"},{"trait_type":"Atmosphere","value":"Tranquil Void"},{"trait_type":"Rarity","value":"Soul Badge"},{"trait_type":"Visual Style","value":"3D Cyber-Cartoon"}]', 50, 30, 'FOCUSED', 'ANALYZED', 'forge-v1', '[{"id":"ded7026bb0ff7a4b5d733aae","url":"https://bee-mbr-ab.imglnk.cn/v/721e0c09d8cbba40c551f86a3e02fb85.png","label":"AGENT DRAFT","name":"尘大师赛博禅","description":"本作「尘大师赛博禅」将原本质朴的手绘冥想意象重构为数字时代的修行图腾。画面中心是一位原创男性卡通角色，保留盘腿冥想、神态温和的核心姿态，但将其转化为半透明的机械义体与霓虹光流交织的形态。背景摒弃了旧牛皮纸的粗糙质感，转而呈现深邃的暗调数字虚空，点缀着若隐若现的全息电路纹理与 brushed metal（拉丝金属）光泽。作品通过“赛博禅意”的视觉隐喻，探讨在信息过载与科技喧嚣中，个体如何寻求内心的静谧与自我和解。这不仅仅是一张图像，更是一枚属于数字游民的灵魂徽章，象征着在虚拟洪流中坚守的精神净土，适合作为 NFT 收藏卡或限量版粉丝周边。","image_prompt":"High-quality square NFT collectible card featuring an original male cartoon character in a lotus meditation pose, floating centrally in a dark cyberpunk digital void. The character retains a gentle, peaceful smile with closed eyes, reimagined with glowing neon outlines in cyan and magenta, blending soft organic shapes with translucent mechanical cybernetic limbs and brushed metal textures. The background is a deep, atmospheric tech space with holographic metal surfaces and faint, glowing circuit board patterns, completely replacing any paper texture. Lighting is cinematic and volumetric, with strong rim lighting highlighting the character''s silhouette against the dark environment to evoke ''Cyber Zen''. Style fusion of 3D render and stylized cartoon, using PBR materials like glowing glass and polished chrome. No text, no logos, no watermarks, no readable typography. Composition is centered and balanced, evoking digital tranquility and inner peace amidst chaos. 8k resolution, octane render, ultra-detailed, macro photography aesthetic.\n\nThis is a personal, non-event fan keepsake inspired by personality, music atmosphere, an imagined scene, daily companionship, or an emotional symbol. Depict portrait-free symbolic memorabilia, a stylized environmental scene, a soft color field, or an original mascot-like emblem. It is not a concert or sports event: no stadium, arena, stage, venue, crowd, audience, performance, or live-show lighting.","attributes":[{"trait_type":"Theme","value":"Cyber Zen"},{"trait_type":"Character State","value":"Digital Meditation"},{"trait_type":"Material","value":"Neon & Brushed Metal"},{"trait_type":"Atmosphere","value":"Tranquil Void"},{"trait_type":"Rarity","value":"Soul Badge"},{"trait_type":"Visual Style","value":"3D Cyber-Cartoon"}]}]', 'ded7026bb0ff7a4b5d733aae', NULL, '2026-08-02T13:30:22.373287', '2026-08-02T13:30:22.373302');
INSERT INTO "nft_forge_sessions" ("id", "user_id", "conversation_id", "template_id", "visual_style", "title", "story_summary", "image_prompt", "reference_image_urls", "suggested_attributes", "supply", "price_fan_tokens", "forge_mode", "status", "rules_version", "generated_versions", "selected_version_id", "published_at", "created_at", "updated_at") VALUES ('2db3655c-a14b-459d-b4e2-dd6276dbd090', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', 'cf11f5005f374cc7a752357e75f04911', '49a46452-507d-4083-b07d-285e42509b27', 'handdrawn', '尘大师禅坐', '用户选择「尘大师」作为 Fanora NFT 的视觉模板，旨在表达一种在喧嚣世界中寻求内心平静、自我和解的禅意状态。故事核心不依赖具体现场回忆，而是聚焦于音乐带来的精神庇护所——一个可以让人盘腿坐下、闭眼微笑、暂时放下重担的私密空间。视觉上将摒弃之前的赛博风格，转而采用极简手绘插画，利用旧棕色牛皮纸的褶皱与纹理象征时间的沉淀，黑色稚拙线条勾勒出一位卷发冥想者，传达出安静、幽默且质朴的治愈力量，如同独立唱片封面般记录一段关于放松与沉思的人生切片。', 'IMAGE-TO-IMAGE REVISION. The supplied reference image is the source of truth. Preserve its main subject, scene type, camera angle, composition, horizon, focal point, recognizable visual identity, and successful material details unless the user explicitly asks to replace them. Improve the artwork as a coherent NFT or fan-merch collectible rather than changing to an unrelated concept. Apply the latest story and art-direction change: 故事状态已经成熟或用户已明确要求生成。严格实现当前作品状态，参考图是视觉主体的第一优先级，必须保留可识别的主体族群、重复图案、构图密度、线条语言和配色关系；保留主视觉、构图层级、材质、色彩、光线和粉丝收藏品形态；不要改成无关场景，不要加入 Logo、水印、可读文字或未经授权的真实人物肖像。.

Base artwork direction: Square NFT collectible art, minimalist hand-drawn illustration style. Central subject: an original male cartoon character sitting in a lotus meditation pose, eyes closed with a gentle peaceful smile, exaggerated curly black hair with subtle 8-bit pixelated texture integration, wearing simple beige long-sleeve clothing. Art style: rough, wobbly, childlike black ink lines with varying thickness, resembling diary doodles or indie album cover art. Background: highly textured old brown kraft paper with visible creases, folds, fiber details, and natural shadows, evoking warmth and time. Composition: centered subject with ample negative space, high contrast between black ink and warm brown paper. Lighting: soft, natural ambient light emphasizing paper texture. Atmosphere: quiet, humorous, rustic, healing, philosophical. No text, no logos, no watermarks. Format: digital collectible card o', '["https://bee-mbr-ab.imglnk.cn/v/e59f0a24a3df1a6014b28f60279b5624.jpg"]', '[{"trait_type":"心境状态","value":"自我和解"},{"trait_type":"视觉材质","value":"旧牛皮纸纹理"},{"trait_type":"线条风格","value":"稚拙手绘"},{"trait_type":"色彩基调","value":"暖棕与墨黑"},{"trait_type":"文化隐喻","value":"独立唱片封面"},{"trait_type":"数字元素","value":"8-bit 卷发细节"}]', 100, 20, 'FOCUSED', 'ANALYZED', 'forge-v1', '[{"id":"c49b8677487dbd6da9260352","url":"https://bee-mbr-ab.imglnk.cn/v/de91aa71dbaa6efb3c8f10f26d5cd477.png","label":"AGENT DRAFT","name":"尘大师禅坐","description":"本作以「尘大师」为精神图腾，描绘在喧嚣世界中寻得内心一隅的禅意瞬间。画面摒弃繁复，回归极简手绘本质：一位卷发男子盘腿冥想，闭目微笑，线条稚拙而抖动，仿佛孩童笔下的纯真记录。背景选用带有明显褶皱与纤维纹理的旧棕色牛皮纸，象征时间的沉淀与生活的粗粝质感。黑色墨线与暖棕底色形成强烈对比，营造出安静、幽默且质朴的治愈氛围。这不仅是一张数字藏品，更是一枚关于自我和解的精神票根，如同独立唱片封面般，珍藏那段放下重担、独自沉思的人生切片。","image_prompt":"IMAGE-TO-IMAGE REVISION. The supplied reference image is the source of truth. Preserve its main subject, scene type, camera angle, composition, horizon, focal point, recognizable visual identity, and successful material details unless the user explicitly asks to replace them. Improve the artwork as a coherent NFT or fan-merch collectible rather than changing to an unrelated concept. Apply the latest story and art-direction change: 故事状态已经成熟或用户已明确要求生成。严格实现当前作品状态，参考图是视觉主体的第一优先级，必须保留可识别的主体族群、重复图案、构图密度、线条语言和配色关系；保留主视觉、构图层级、材质、色彩、光线和粉丝收藏品形态；不要改成无关场景，不要加入 Logo、水印、可读文字或未经授权的真实人物肖像。.\n\nBase artwork direction: Square NFT collectible art, minimalist hand-drawn illustration style. Central subject: an original male cartoon character sitting in a lotus meditation pose, eyes closed with a gentle peaceful smile, exaggerated curly black hair with subtle 8-bit pixelated texture integration, wearing simple beige long-sleeve clothing. Art style: rough, wobbly, childlike black ink lines with varying thickness, resembling diary doodles or indie album cover art. Background: highly textured old brown kraft paper with visible creases, folds, fiber details, and natural shadows, evoking warmth and time. Composition: centered subject with ample negative space, high contrast between black ink and warm brown paper. Lighting: soft, natural ambient light emphasizing paper texture. Atmosphere: quiet, humorous, rustic, healing, philosophical. No text, no logos, no watermarks. Format: digital collectible card o","attributes":[{"trait_type":"心境状态","value":"自我和解"},{"trait_type":"视觉材质","value":"旧牛皮纸纹理"},{"trait_type":"线条风格","value":"稚拙手绘"},{"trait_type":"色彩基调","value":"暖棕与墨黑"},{"trait_type":"文化隐喻","value":"独立唱片封面"},{"trait_type":"数字元素","value":"8-bit 卷发细节"}]}]', 'c49b8677487dbd6da9260352', NULL, '2026-08-02T13:32:40.302089', '2026-08-02T13:32:40.302097');
INSERT INTO "nft_forge_sessions" ("id", "user_id", "conversation_id", "template_id", "visual_style", "title", "story_summary", "image_prompt", "reference_image_urls", "suggested_attributes", "supply", "price_fan_tokens", "forge_mode", "status", "rules_version", "generated_versions", "selected_version_id", "published_at", "created_at", "updated_at") VALUES ('47f73c72-a01c-4188-bd74-0ccee64d3eee', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', 'cf11f5005f374cc7a752357e75f04911', '49a46452-507d-4083-b07d-285e42509b27', 'handdrawn', '尘心自洽', '一段正在形成的真实粉丝记忆', 'Square pixel art collectible, 8-bit retro game aesthetic. Central subject: an original male character sitting cross-legged in meditation, eyes closed with a gentle smile, exaggerated curly black hair, wearing simple brown and beige pixelated clothes. Background: warm old brown kraft paper texture reinterpreted as a pixel grid, showing visible folds and fiber patterns in low-res style. Composition: centered character with ample negative space, no readable text, no logos. Colors: earthy browns, beige, stark black outlines, bright accent colors for a nostalgic video game feel. Lighting: flat, even retro lighting with soft pixel shadows. Atmosphere: quiet, healing, humorous, philosophical, like a limited edition indie game cartridge cover or digital badge. High quality, sharp pixels, vibrant yet warm palette.

This is a personal, non-event fan keepsake inspired by personality, music atmosphere, an imagined scene, daily companionship, or an emotional symbol. Depict portrait-free symbolic memorabilia, a stylized environmental scene, a soft color field, or an original mascot-like emblem. It is not a concert or sports event: no stadium, arena, stage, venue, crowd, audience, performance, or live-show lighting.', '["https://bee-mbr-ab.imglnk.cn/v/e59f0a24a3df1a6014b28f60279b5624.jpg"]', '[{"trait_type":"Style","value":"8-Bit Retro"},{"trait_type":"Mood","value":"Self-Reconciliation"},{"trait_type":"Texture","value":"Pixelated Kraft Paper"},{"trait_type":"Character State","value":"Meditating"},{"trait_type":"Rarity","value":"Fan Keepsake"},{"trait_type":"Color Palette","value":"Warm Earth Tones"}]', 500, 30, 'FOCUSED', 'PUBLISHED', 'forge-v1', '[{"id":"ddf67634616c17d56ee4e56b","url":"https://bee-mbr-ab.imglnk.cn/v/733c9c2249024126416d99eac5bb1d42.png","label":"AGENT DRAFT","name":"尘心自洽","description":"作品源自一段正在形成的真实粉丝记忆，以“尘大师”的意象隐喻自我和解的宁静时刻。画面重构为 8-bit 像素艺术风格，将原本手绘的冥想者转化为复古游戏中的治愈系角色。背景保留了旧牛皮纸的温暖棕色调与纤维质感，但通过像素网格重新诠释，营造出数字怀旧与手工温度交织的独特氛围。中央人物盘腿而坐，闭目微笑，夸张的卷发与简约衣着以明亮的色块呈现，既保留了原作的稚拙幽默，又增添了电子收藏品的趣味性与稀缺感。这不仅是一张专辑封面的数字变体，更是一枚象征内心平静与日常陪伴的像素徽章，记录着粉丝在音乐中找到共鸣的纯粹瞬间。","image_prompt":"Square pixel art collectible, 8-bit retro game aesthetic. Central subject: an original male character sitting cross-legged in meditation, eyes closed with a gentle smile, exaggerated curly black hair, wearing simple brown and beige pixelated clothes. Background: warm old brown kraft paper texture reinterpreted as a pixel grid, showing visible folds and fiber patterns in low-res style. Composition: centered character with ample negative space, no readable text, no logos. Colors: earthy browns, beige, stark black outlines, bright accent colors for a nostalgic video game feel. Lighting: flat, even retro lighting with soft pixel shadows. Atmosphere: quiet, healing, humorous, philosophical, like a limited edition indie game cartridge cover or digital badge. High quality, sharp pixels, vibrant yet warm palette.\n\nThis is a personal, non-event fan keepsake inspired by personality, music atmosphere, an imagined scene, daily companionship, or an emotional symbol. Depict portrait-free symbolic memorabilia, a stylized environmental scene, a soft color field, or an original mascot-like emblem. It is not a concert or sports event: no stadium, arena, stage, venue, crowd, audience, performance, or live-show lighting.","attributes":[{"trait_type":"Style","value":"8-Bit Retro"},{"trait_type":"Mood","value":"Self-Reconciliation"},{"trait_type":"Texture","value":"Pixelated Kraft Paper"},{"trait_type":"Character State","value":"Meditating"},{"trait_type":"Rarity","value":"Fan Keepsake"},{"trait_type":"Color Palette","value":"Warm Earth Tones"}]}]', 'ddf67634616c17d56ee4e56b', '2026-08-02T13:41:04.740591', '2026-08-02T13:37:51.335180', '2026-08-02T13:41:04.740610');

