INSERT INTO "nft_metadata_versions" ("id", "subject_type", "subject_id", "version", "image_cid", "image_pin_id", "metadata_cid", "metadata_pin_id", "content_hash", "size_bytes", "mime_type", "pin_status", "metadata_payload", "created_by_user_id", "created_at") VALUES ('b2c87bc9-3319-4d14-b474-3d43676835b8', 'FAN_LIMITED_NFT', '99abd959-53a5-4996-8306-c2da3aba3da4', 1, 'bafybeiagksd62d6goskmfsakrtlmh5wj4xhl2sw7ptujlhexomzppwwg2a', '019fc261-f4e9-71d1-9ab0-d27915f7ae8d', 'bafkreibh7s2gvwmnqfre6pojp3qgytkf2n4badcqqfc6uguin3wbyoe3hi', '019fc262-13c3-7945-8be8-5e2322e4e2e0', '77fcb3580b8611e5841fc65dc3d56a894b9782f9061711697a7adbf625adfc0b', 1475129, 'image/png', 'PINNED', '{"name":"0xaC9612 · 安可绽放时","description":"这是一枚凝固了演唱会最高潮瞬间的数字纪念票根。作品以横向悬浮的 3D 纸质票根为载体，左侧主画面将粉丝记忆中的镜像侧脸转化为温柔细腻的手绘插画：两抹背对背的剪影在舞台暖金逆光中静默伫立，象征着时间与自我的深情对话。缤纷的彩带如记忆碎片般在周身飞舞，与底部隐约的人群剪影交织，重现现场的热烈与感动。右侧保留经典的半圆缺口与虚线打孔副券，整体采用清新明亮的 pastel 色调与柔和投影，既是对那场梦境的温柔复刻，也是专属粉丝的情感资产，适合永久珍藏于数字钱包或作为社群身份徽章。","image":"ipfs://bafybeiagksd62d6goskmfsakrtlmh5wj4xhl2sw7ptujlhexomzppwwg2a","category":"FAN_LIMITED_NFT","issuer":"Fanora Protocol","theme":"演唱会纪念票根","attributes":[{"trait_type":"收藏形态","value":"3D 悬浮票根"},{"trait_type":"视觉风格","value":"温柔手绘插画"},{"trait_type":"核心意象","value":"镜像侧脸与彩带"},{"trait_type":"光影氛围","value":"舞台暖金逆光"},{"trait_type":"情感基调","value":"怀旧庆典"},{"trait_type":"材质质感","value":"细腻纹理纸张"},{"trait_type":"Category","value":"FAN_LIMITED_NFT"},{"trait_type":"Max Supply","value":"100"},{"trait_type":"Price FAN","value":"20"},{"trait_type":"Rare Score","value":"76"},{"trait_type":"Rarity Level","value":"Special"},{"trait_type":"Fan Emotion","value":"80"},{"trait_type":"Forge Result","value":"Success"},{"trait_type":"Rules Version","value":"forge-v1"}]}', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', '2026-08-02T12:10:37.210536+00:00');
INSERT INTO "nft_metadata_versions" ("id", "subject_type", "subject_id", "version", "image_cid", "image_pin_id", "metadata_cid", "metadata_pin_id", "content_hash", "size_bytes", "mime_type", "pin_status", "metadata_payload", "created_by_user_id", "created_at") VALUES ('0d224e9b-8d39-429b-a8de-64c94ab7b885', 'FAN_LIMITED_NFT', '94c11f0e-3df0-4e40-b9e4-218f15de72f4', 1, 'bafybeici7vti4y6b5o73l42j45wbw4623mwpww64nyhzkbtbmplvwycude', '019fc26d-6af1-7925-b15f-c0f6c3b89dee', 'bafkreifntcznnbukpfkp7v7ltlk423xci7r62jee4ax5stoqja2k4snkiq', '019fc26d-7bac-7482-b8df-0a59abe4863a', '781cfdb94f5bf622205488f35eec259e36179ba35a7b1964c3250c22f22d2194', 761483, 'image/png', 'PINNED', '{"name":"0xaC9612 · 写给这份喜欢的喜欢","description":"这份 NFT 记录的是：用户基于陈奕迅的视觉模板发起创作，提取了“成熟克制、略带疲惫、幽默内敛”的气质特征，以及“西装革履却略显忙乱、佩戴耳机”的视觉元素。创作核心从单纯的艺人肖像转化为一种普世的粉丝情感投射：在繁忙的成人世界（西装、便签、歪斜领带）中，依然通过音乐（耳机）守护内心秩序的普通人形象。视觉风格选定为 Chibi，旨在用柔和可爱的形式消解现实的沉重，强调“陪伴”与“自我和解”的情感价值。。它不补写未发生的演出、现场或共同经历，只保留粉丝亲自表达的欣赏与情绪。## 小标题","image":"ipfs://bafybeici7vti4y6b5o73l42j45wbw4623mwpww64nyhzkbtbmplvwycude","category":"FAN_LIMITED_NFT","issuer":"Fanora Protocol","theme":"陈奕迅","attributes":[{"trait_type":"故事主角","value":"的形式消解"},{"trait_type":"情感","value":"欣赏与喜欢"},{"trait_type":"Category","value":"FAN_LIMITED_NFT"},{"trait_type":"Max Supply","value":"100"},{"trait_type":"Price FAN","value":"20"},{"trait_type":"Rare Score","value":"70"},{"trait_type":"Rarity Level","value":"Special"},{"trait_type":"Fan Emotion","value":"80"},{"trait_type":"Forge Result","value":"Success"},{"trait_type":"Rules Version","value":"forge-v1"}]}', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', '2026-08-02T12:23:04.958781+00:00');
INSERT INTO "nft_metadata_versions" ("id", "subject_type", "subject_id", "version", "image_cid", "image_pin_id", "metadata_cid", "metadata_pin_id", "content_hash", "size_bytes", "mime_type", "pin_status", "metadata_payload", "created_by_user_id", "created_at") VALUES ('58ab9e09-6373-4dd6-ada6-f6d32361fe29', 'FAN_LIMITED_NFT', '2707299e-36aa-4966-8f8f-25c91ed00bad', 1, 'bafybeiessufsfgeh43vfnm7qx3he25p76mjyofjmdn3g6gx7ybarsobzk4', '019fc271-5542-7f34-8e33-82f757f330a4', 'bafkreihpzvnlxwdbjxvq25d54zailnzffkjdpbh3db5jhqzs7jcukfgtnm', '019fc271-6628-717c-802f-fb6418b940d8', '0eafb9021021e9e6877d8b68d5b12a73b90515e0b1547df4a9e6fd37b9a87e45', 1355690, 'image/png', 'PINNED', '{"name":"0xaC9612 · 霓虹情绪圆脸","description":"本作以手绘涂鸦为核心语言，将粉丝群体在音乐共鸣中瞬息万变的情绪具象化为数十个色彩斑斓的圆形面孔。作品摒弃具象场景，转而通过随性不完美的黑色线条与高饱和霓虹色块的层叠交错，构建出一种独立音乐周边的独特质感。Risograph 印刷特有的错位纹理与纸张颗粒感，赋予了数字藏品实体收藏的温度，寓意每一位听众都是这团黑色背景中不可或缺的独特光点，共同组成了这场永不散场的内心狂欢。","image":"ipfs://bafybeiessufsfgeh43vfnm7qx3he25p76mjyofjmdn3g6gx7ybarsobzk4","category":"FAN_LIMITED_NFT","issuer":"Fanora Protocol","theme":"周边形象","attributes":[{"trait_type":"Visual Style","value":"Hand-drawn Doodle"},{"trait_type":"Texture","value":"Risograph Print"},{"trait_type":"Color Palette","value":"Neon 8-bit"},{"trait_type":"Composition","value":"Dense Overlap"},{"trait_type":"Vibe","value":"Whimsical Energy"},{"trait_type":"Collectible Type","value":"Indie Merch Art"},{"trait_type":"Category","value":"FAN_LIMITED_NFT"},{"trait_type":"Max Supply","value":"50"},{"trait_type":"Price FAN","value":"3000"},{"trait_type":"Rare Score","value":"83"},{"trait_type":"Rarity Level","value":"Rare"},{"trait_type":"Fan Emotion","value":"75"},{"trait_type":"Forge Result","value":"Success"},{"trait_type":"Rules Version","value":"forge-v1"}]}', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', '2026-08-02T12:27:21.387124+00:00');
