INSERT INTO "membership_identity_nfts" ("id", "user_id", "wallet_address", "chain_id", "contract_address", "token_id", "level_id", "level_code", "metadata_version", "metadata_cid", "status", "chain_operation_id", "minted_at", "created_at", "updated_at", "is_member_card", "card_level_code", "card_content_hash", "card_fee_fan_tokens", "card_created_at", "card_updated_at") VALUES ('8dbad1b2-5fb7-4f52-999d-9a4bbe5c603f', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', '0xaC961208D21E0cDeC56F146F61Ec4cF20fd8eaF5', 10143, '0xee3c3f36ff43acb44f0f8271fbe7cdbaacaf5c85', 6, 3, 'moderate-neuro', 6, 'bafkreihx7zepg3a6r6bw2tp5cqnutyk6nlmejvg3xw4tpts7q3va4jwx6a', 'CONFIRMED', 'bc19afea-9869-4136-a97c-080fb8ebfe51', '2026-07-23T13:17:10.243402+00:00', '2026-07-23T13:17:02.777436+00:00', '2026-08-02T12:28:34.671123+00:00', TRUE, 'moderate-neuro', '58fd2b850507a34ae015dacb018079255774ccaffc0e5487c26824fd28bcb0d2', 0, '2026-07-23T13:17:52.834481', '2026-08-02T12:28:34.671123');

-- table: nft_ai_analyses, rows: 18
INSERT INTO "nft_ai_analyses" ("id", "forge_session_id", "rare_score", "rarity_level", "originality", "visual_quality", "fan_emotion", "scarcity", "community_potential", "recommend_supply_min", "recommend_supply_max", "recommend_supply_default", "recommend_price_min", "recommend_price_max", "recommend_price_default", "suggestions", "model_name", "prompt_version", "created_at", "updated_at") VALUES ('5604f65a-a167-413f-a2bc-12f8a87a9c7f', '8977da0f-a660-4a33-a88f-3774e75e79e7', 74, 'Special', 78, 85, 72, 65, 60, 50, 300, 100, 10, 40, 20, '["将故事中的''未知的注视''具体化为一次真实的演出经历（如：某次谢幕时突然感受到的寒意，或后台特定的传闻），以增强情感共鸣和原创性。","在视觉 Brief 中明确''模糊轮廓''的具体特征暗示（如：特殊的戏服残片、非人的肢体比例），避免生成过于通用的恐怖剪影。","补充关于''10 枚发行量''的分配逻辑或持有者权益（如：是否包含幕后花絮音频），以提升社区讨论潜力和稀缺感知的合理性。"]', 'Qwen/Qwen3.5-397B-A17B', 'nft-forge-analysis-v1', '2026-07-31T22:54:09.296411', '2026-07-31T22:54:09.296423');
INSERT INTO "nft_ai_analyses" ("id", "forge_session_id", "rare_score", "rarity_level", "originality", "visual_quality", "fan_emotion", "scarcity", "community_potential", "recommend_supply_min", "recommend_supply_max", "recommend_supply_default", "recommend_price_min", "recommend_price_max", "recommend_price_default", "suggestions", "model_name", "prompt_version", "created_at", "updated_at") VALUES ('e0257f8b-adf6-4d23-ae40-f3e59dc2a371', '32f33816-3ebc-4f8e-8f0a-2b35730a5088', 60, 'Normal', 58, 74, 57, 55, 59, 100, 500, 200, 5, 25, 10, '["保留当前故事核心，并让象征物成为画面第一视觉焦点"]', 'rules', 'nft-forge-analysis-v1', '2026-08-02T05:18:38.072938', '2026-08-02T05:18:38.072949');
INSERT INTO "nft_ai_analyses" ("id", "forge_session_id", "rare_score", "rarity_level", "originality", "visual_quality", "fan_emotion", "scarcity", "community_potential", "recommend_supply_min", "recommend_supply_max", "recommend_supply_default", "recommend_price_min", "recommend_price_max", "recommend_price_default", "suggestions", "model_name", "prompt_version", "created_at", "updated_at") VALUES ('8836c4a2-9c75-41f2-9aa8-1184c42619f9', '6fc1ea9e-9c35-41c9-b952-c7368b8f7d13', 81, 'Rare', 75, 90, 80, 85, 70, 10, 100, 50, 20, 60, 30, '["在故事摘要中补充一首具体歌曲或歌词，描述该旋律如何化作‘守护者轮廓’陪伴你度过某个独处时刻，以增强情感共鸣的独特性。","细化‘情绪线条’的视觉隐喻，例如说明烫金线条的流动方向或形态是否象征着呼吸、心跳或特定的记忆片段。","考虑为‘静默守护’系列增加一个简短的创作者寄语或粉丝互动话题，鼓励社区分享各自心中的‘沉默陪伴’瞬间。"]', 'Qwen/Qwen3.5-397B-A17B', 'nft-forge-analysis-v1', '2026-08-02T06:59:31.221830', '2026-08-02T06:59:31.221846');
INSERT INTO "nft_ai_analyses" ("id", "forge_session_id", "rare_score", "rarity_level", "originality", "visual_quality", "fan_emotion", "scarcity", "community_potential", "recommend_supply_min", "recommend_supply_max", "recommend_supply_default", "recommend_price_min", "recommend_price_max", "recommend_price_default", "suggestions", "model_name", "prompt_version", "created_at", "updated_at") VALUES ('1cffe76c-1f15-4b60-968d-fb22814ee632', '13050724-5350-4e73-851f-449408022f2d', 52, 'Normal', 45, 60, 50, 55, 50, 100, 500, 200, 5, 25, 10, '["将抽象的“这份喜欢”转化为具体的感官细节，例如描述一首特定歌曲带来的想象场景、一种代表性格的颜色，或是一个日常陪伴的微小物件。","在视觉 Brief 中补充具体的材质质感（如磨砂、镭射、半透明）和光影氛围描述，以替代对参考图的单纯依赖，提升画面独特性。","挖掘一段私人的心路历程或独家记忆作为故事核心，避免使用通用的情感模板，让收藏品具有不可替代的情感重量。"]', 'Qwen/Qwen3.5-397B-A17B', 'nft-forge-analysis-v1', '2026-08-02T07:04:31.179667', '2026-08-02T07:04:31.179681');
INSERT INTO "nft_ai_analyses" ("id", "forge_session_id", "rare_score", "rarity_level", "originality", "visual_quality", "fan_emotion", "scarcity", "community_potential", "recommend_supply_min", "recommend_supply_max", "recommend_supply_default", "recommend_price_min", "recommend_price_max", "recommend_price_default", "suggestions", "model_name", "prompt_version", "created_at", "updated_at") VALUES ('a150eabd-1eb7-4bbe-9f0d-07d9eaaa6bbc', '2c8e15dc-4b01-4987-990b-99d4d6b409ac', 68, 'Special', 65, 85, 60, 70, 55, 50, 300, 100, 10, 40, 20, '["补充一首对你意义非凡的具体歌曲名称，描述前奏响起时你正在做的具体动作（如：雨夜关窗、末班地铁闭眼），将‘通用陪伴’转化为‘独家记忆’。","在视觉 Brief 中增加一个具象的私人符号（如：票根角落的一枚特定年份邮票、一道模拟咖啡渍的痕迹），以增强物品的故事真实感。","简述一个因这首歌而改变的性格瞬间或决定，让‘心灵契约’的概念拥有更扎实的情感锚点。"]', 'Qwen/Qwen3.5-397B-A17B', 'nft-forge-analysis-v1', '2026-08-02T07:36:32.665325', '2026-08-02T07:36:32.665340');
INSERT INTO "nft_ai_analyses" ("id", "forge_session_id", "rare_score", "rarity_level", "originality", "visual_quality", "fan_emotion", "scarcity", "community_potential", "recommend_supply_min", "recommend_supply_max", "recommend_supply_default", "recommend_price_min", "recommend_price_max", "recommend_price_default", "suggestions", "model_name", "prompt_version", "created_at", "updated_at") VALUES ('e7c653f1-db63-4d4e-9ab8-958fbbde3932', 'dfeb01c7-8757-46ee-b672-edae7a098883', 68, 'Special', 65, 80, 60, 75, 55, 50, 300, 100, 10, 40, 20, '["将抽象的“这份喜欢”具象化为一个具体的日常陪伴场景（如：耳机里的特定旋律时刻、深夜循环的某句歌词），以增强情感共鸣。","在视觉描述中补充具体的色彩情绪对应关系，例如说明为何选择霓虹色系来代表这种欣赏，使色彩选择更具故事性。","细化“手绘涂鸦”风格中的独特细节，比如为吉祥物添加一个代表你个人性格特征的专属符号或动作，提升原创辨识度。"]', 'Qwen/Qwen3.5-397B-A17B', 'nft-forge-analysis-v1', '2026-08-02T07:56:08.453597', '2026-08-02T07:56:08.453605');
INSERT INTO "nft_ai_analyses" ("id", "forge_session_id", "rare_score", "rarity_level", "originality", "visual_quality", "fan_emotion", "scarcity", "community_potential", "recommend_supply_min", "recommend_supply_max", "recommend_supply_default", "recommend_price_min", "recommend_price_max", "recommend_price_default", "suggestions", "model_name", "prompt_version", "created_at", "updated_at") VALUES ('dd7569c4-e0ed-4c06-a38f-807e5b21b40e', '05e48243-d172-4d78-96fb-240d987d39bc', 88, 'Rare', 88, 92, 85, 90, 82, 10, 100, 50, 20, 60, 30, '["在故事摘要中补充一首对该用户具有特殊意义的歌曲名称或歌词片段，描述其如何触发‘自我对话’的具体心境，以增强情感共鸣。","细化‘记忆碎片’的视觉定义，例如是否包含特定的旧物（如褪色手环、干花）或抽象的光影形态，使超现实元素更具个人叙事性。","考虑为这枚票根设定一个虚构的‘演出日期’或‘场馆名称’作为背景纹理细节，虽非真实经历，但能完善世界观的沉浸感。"]', 'Qwen/Qwen3.5-397B-A17B', 'nft-forge-analysis-v1', '2026-08-02T08:25:26.367872', '2026-08-02T08:25:26.367886');
INSERT INTO "nft_ai_analyses" ("id", "forge_session_id", "rare_score", "rarity_level", "originality", "visual_quality", "fan_emotion", "scarcity", "community_potential", "recommend_supply_min", "recommend_supply_max", "recommend_supply_default", "recommend_price_min", "recommend_price_max", "recommend_price_default", "suggestions", "model_name", "prompt_version", "created_at", "updated_at") VALUES ('65991813-0698-4837-9119-151e030cc801', 'c92f8e29-2358-41af-8dc2-9e86fc51de0c', 88, 'Rare', 88, 92, 95, 75, 85, 10, 100, 50, 20, 60, 30, '["在票根背面或隐藏层加入一句用户个人最共鸣的歌词手写体（非标准字体），增强独家记忆属性。","细化‘梦境花园’中花朵的种类象征，例如将特定花朵与用户听歌时的具体生活场景（如雨天、深夜）关联，深化故事层次。","考虑为 50 枚发行量设计微小的变量（如彩带颜色或光束角度的随机种子），让每一枚‘回响’都有独特的视觉指纹。"]', 'Qwen/Qwen3.5-397B-A17B', 'nft-forge-analysis-v1', '2026-08-02T08:27:56.872437', '2026-08-02T08:27:56.872457');
INSERT INTO "nft_ai_analyses" ("id", "forge_session_id", "rare_score", "rarity_level", "originality", "visual_quality", "fan_emotion", "scarcity", "community_potential", "recommend_supply_min", "recommend_supply_max", "recommend_supply_default", "recommend_price_min", "recommend_price_max", "recommend_price_default", "suggestions", "model_name", "prompt_version", "created_at", "updated_at") VALUES ('acd3b357-68c8-416a-b288-252549fbc0f9', '6f8cb8cc-115f-44cc-bfd0-1253630e6fe4', 85, 'Rare', 88, 92, 85, 78, 82, 10, 100, 50, 20, 60, 30, '["在故事摘要中补充一段具体的个人听歌记忆或梦境细节（如某句歌词引发的具体画面），以增强情感共鸣的独特性。","细化“记忆碎片”的具体视觉形态，例如将其描述为旧磁带、泛黄照片或特定颜色的光点，使超现实元素更具叙事指向。","明确“黑白摄影质感”与“彩色花园”之间的光影交互逻辑，例如描述花朵的光芒如何映照在人物面部，提升画面整体的融合度。"]', 'Qwen/Qwen3.5-397B-A17B', 'nft-forge-analysis-v1', '2026-08-02T08:30:23.365518', '2026-08-02T08:30:23.365534');
INSERT INTO "nft_ai_analyses" ("id", "forge_session_id", "rare_score", "rarity_level", "originality", "visual_quality", "fan_emotion", "scarcity", "community_potential", "recommend_supply_min", "recommend_supply_max", "recommend_supply_default", "recommend_price_min", "recommend_price_max", "recommend_price_default", "suggestions", "model_name", "prompt_version", "created_at", "updated_at") VALUES ('b7256aea-03a5-4151-8c89-30d6edf19d93', '499e0623-c526-4825-bf2d-d5e9e0739268', 85, 'Rare', 88, 92, 85, 78, 82, 10, 100, 50, 20, 60, 30, '["在元数据或配套文案中补充一段关于‘双生自我’的具体心路历程，例如某首特定歌曲如何引发这种内心对话，以增强情感共鸣。","细化‘机械花朵’的品种设定，将其与粉丝社群内的特定梗或共同记忆符号对应，增加收藏的解读深度。","考虑为 50 枚发行量设计微小的变量（如光纤颜色或碎片形状），让每一枚票根拥有独一无二的‘记忆指纹’。"]', 'Qwen/Qwen3.5-397B-A17B', 'nft-forge-analysis-v1', '2026-08-02T08:32:04.176774', '2026-08-02T08:32:04.176795');
INSERT INTO "nft_ai_analyses" ("id", "forge_session_id", "rare_score", "rarity_level", "originality", "visual_quality", "fan_emotion", "scarcity", "community_potential", "recommend_supply_min", "recommend_supply_max", "recommend_supply_default", "recommend_price_min", "recommend_price_max", "recommend_price_default", "suggestions", "model_name", "prompt_version", "created_at", "updated_at") VALUES ('026aec75-f69e-4a6a-98d9-3da87ca082b9', '4f8ebfe4-eb45-43df-95ab-2642c3a21c96', 77, 'Special', 75, 85, 70, 80, 75, 50, 300, 100, 10, 40, 20, '["在故事摘要中补充一个具体的“内省时刻”或触发这种情绪的真实生活场景，让抽象的符号与个人记忆产生强关联。","尝试为这个“粉圆”赋予一个具体的性格设定或名字，使其成为粉丝社群中代表“宁静”或“自我对话”的图腾角色。","可以描述一下这个表情让你联想到哪首歌曲的间奏或哪段旋律，用听觉通感来丰富视觉背后的故事层次。"]', 'Qwen/Qwen3.5-397B-A17B', 'nft-forge-analysis-v1', '2026-08-02T09:49:08.007978', '2026-08-02T09:49:08.007986');
INSERT INTO "nft_ai_analyses" ("id", "forge_session_id", "rare_score", "rarity_level", "originality", "visual_quality", "fan_emotion", "scarcity", "community_potential", "recommend_supply_min", "recommend_supply_max", "recommend_supply_default", "recommend_price_min", "recommend_price_max", "recommend_price_default", "suggestions", "model_name", "prompt_version", "created_at", "updated_at") VALUES ('2fd26530-f811-4b9d-b37b-84be7151ec89', 'e5790ba7-384d-43f7-94e1-2d0efcd14aab', 76, 'Special', 75, 85, 80, 70, 65, 50, 300, 100, 10, 40, 20, '["在故事摘要中补充一首对你意义非凡的演唱会曲目，描述听到它时脑海中浮现的具体画面，以增强情感共鸣。","尝试描述一种具体的‘记忆碎片’形态（如：一张旧车票、一句歌词的手写体），将其融入视觉描述中，使梦境更具个人专属感。","可以简述你为何选择‘镜像侧脸’这一意象，是象征过去的自己与现在的对话，还是某种特定的性格特质，这能提升作品的叙事深度。"]', 'Qwen/Qwen3.5-397B-A17B', 'nft-forge-analysis-v1', '2026-08-02T12:09:02.260464', '2026-08-02T12:09:02.260477');
INSERT INTO "nft_ai_analyses" ("id", "forge_session_id", "rare_score", "rarity_level", "originality", "visual_quality", "fan_emotion", "scarcity", "community_potential", "recommend_supply_min", "recommend_supply_max", "recommend_supply_default", "recommend_price_min", "recommend_price_max", "recommend_price_default", "suggestions", "model_name", "prompt_version", "created_at", "updated_at") VALUES ('d3fe2b20-9cbf-4239-9d64-145d94dad20e', 'edbbd798-6384-4540-8b49-8a330c74f5d1', 70, 'Special', 65, 70, 80, 60, 75, 50, 300, 100, 10, 40, 20, '["视觉风格与 Brief 存在偏差：Brief 要求 Chibi（Q 版）风格，但实际图片为写实比例插画，建议调整画风以符合设定。","图片中人物面部特征过于具体，建议进一步抽象化或采用背影/侧影处理，以符合''肖像无关（portrait-free）''的收藏定义，增强普世共鸣。","故事核心''形式消解''较为抽象，建议在视觉元素中增加具体的象征物（如被音乐融化的领带、发光的耳机线等）来具象化这一概念。"]', 'Qwen/Qwen3.5-397B-A17B', 'nft-forge-analysis-v1', '2026-08-02T12:20:06.805406', '2026-08-02T12:20:06.805419');
INSERT INTO "nft_ai_analyses" ("id", "forge_session_id", "rare_score", "rarity_level", "originality", "visual_quality", "fan_emotion", "scarcity", "community_potential", "recommend_supply_min", "recommend_supply_max", "recommend_supply_default", "recommend_price_min", "recommend_price_max", "recommend_price_default", "suggestions", "model_name", "prompt_version", "created_at", "updated_at") VALUES ('a5d40412-4856-4a61-b358-1a0b08e8e66c', '38cef892-d02c-47d8-9906-2aa370087e44', 83, 'Rare', 82, 88, 75, 90, 85, 10, 100, 50, 20, 60, 30, '["建议移除画面中央的 ''FEAR and DREAMS'' 文字，以符合视觉提示词中 ''No text'' 的要求，使构图更纯粹地聚焦于圆脸角色的活力。","可以在故事摘要中补充一两个具体的歌词片段或听歌场景，解释这些圆脸表情分别对应歌曲中的哪些情绪转折，增强情感共鸣。","考虑为这组圆脸设定一个具体的互动玩法，例如持有者可以认领其中一个表情作为自己的 ''听歌状态''，增加社区互动的趣味性。"]', 'Qwen/Qwen3.5-397B-A17B', 'nft-forge-analysis-v1', '2026-08-02T12:25:20.708593', '2026-08-02T12:25:20.708603');
INSERT INTO "nft_ai_analyses" ("id", "forge_session_id", "rare_score", "rarity_level", "originality", "visual_quality", "fan_emotion", "scarcity", "community_potential", "recommend_supply_min", "recommend_supply_max", "recommend_supply_default", "recommend_price_min", "recommend_price_max", "recommend_price_default", "suggestions", "model_name", "prompt_version", "created_at", "updated_at") VALUES ('f0fe4351-6bf9-408e-a939-575af6e719a7', 'c3196b0b-050d-42ce-aa74-5a0cf7961d4c', 75, 'Special', 75, 88, 70, 65, 80, 50, 300, 100, 10, 40, 20, '["建议将‘未来都市’的通用设定替换为陈奕迅某首具体歌曲（如《孤勇者》或《任我行》）中的标志性意象，以增强故事独特性。","目前的视觉呈现偏向‘恐惧与梦想’专辑的官方艺术风格，建议在剪影内部加入更多个人化的生活场景或情感符号，减少通用素材感。","可以在 Brief 中补充一段关于这首歌如何陪伴你度过某个具体时刻的简短描述，让‘聆听者’的形象更具血肉。"]', 'Qwen/Qwen3.5-397B-A17B', 'nft-forge-analysis-v1', '2026-08-02T12:37:35.904958', '2026-08-02T12:37:35.904997');
INSERT INTO "nft_ai_analyses" ("id", "forge_session_id", "rare_score", "rarity_level", "originality", "visual_quality", "fan_emotion", "scarcity", "community_potential", "recommend_supply_min", "recommend_supply_max", "recommend_supply_default", "recommend_price_min", "recommend_price_max", "recommend_price_default", "suggestions", "model_name", "prompt_version", "created_at", "updated_at") VALUES ('ce264c1f-d305-4ea8-b937-97f32d0f4a64', '2f64d566-4f8d-4926-bbef-30b58a3996c6', 81, 'Rare', 85, 75, 90, 70, 80, 10, 100, 50, 20, 60, 30, '["建议在视觉设计中保留原图标志性的黄色背景或黑色粗线条，作为连接‘质朴手绘’与‘赛博朋克’风格的视觉锚点，增强辨识度。","可以将‘尘大师’的发型或五官特征进行更具体的赛博化重构（如机械发丝、全息面部），以强化‘数字修行’的独特性。","在元数据或描述中补充这首歌对你个人生活的具体陪伴场景（如通勤、睡前），让‘自我和解’的主题更具情感共鸣。"]', 'Qwen/Qwen3.5-397B-A17B', 'nft-forge-analysis-v1', '2026-08-02T13:30:22.381766', '2026-08-02T13:30:22.381780');
INSERT INTO "nft_ai_analyses" ("id", "forge_session_id", "rare_score", "rarity_level", "originality", "visual_quality", "fan_emotion", "scarcity", "community_potential", "recommend_supply_min", "recommend_supply_max", "recommend_supply_default", "recommend_price_min", "recommend_price_max", "recommend_price_default", "suggestions", "model_name", "prompt_version", "created_at", "updated_at") VALUES ('277e0fa4-df36-4a44-8ae3-403bf94660be', '2db3655c-a14b-459d-b4e2-dd6276dbd090', 74, 'Special', 75, 60, 85, 70, 80, 50, 300, 100, 10, 40, 20, '["视觉执行与 Brief 存在较大偏差：参考图使用了高饱和度的亮黄色背景，而 Brief 明确要求‘旧棕色牛皮纸纹理’和‘暖棕与墨黑’基调。建议调整背景材质以符合‘时间沉淀’的叙事需求。","参考图中包含了‘尘大师’和‘eason chan’的手写文字，但 Brief 明确要求‘No text, no logos’。为了保持画面的纯粹性和作为独立艺术品的收藏价值，建议移除文字，仅保留视觉符号。","故事核心在于‘音乐带来的精神庇护所’，建议在描述中补充一两句具体的听歌场景（例如：是在深夜加班后，还是通勤路上），让‘自我和解’的情绪有更具体的落脚点，增强共鸣。"]', 'Qwen/Qwen3.5-397B-A17B', 'nft-forge-analysis-v1', '2026-08-02T13:32:40.304802', '2026-08-02T13:32:40.304813');
INSERT INTO "nft_ai_analyses" ("id", "forge_session_id", "rare_score", "rarity_level", "originality", "visual_quality", "fan_emotion", "scarcity", "community_potential", "recommend_supply_min", "recommend_supply_max", "recommend_supply_default", "recommend_price_min", "recommend_price_max", "recommend_price_default", "suggestions", "model_name", "prompt_version", "created_at", "updated_at") VALUES ('62fa98dc-5b38-4756-9738-aab34536776c', '47f73c72-a01c-4188-bd74-0ccee64d3eee', 82, 'Rare', 85, 78, 88, 75, 82, 10, 100, 50, 20, 60, 30, '["在故事摘要中补充一段具体的个人经历，例如这首歌是在什么生活阶段陪伴你度过难关的，或者这个冥想姿态代表了你对自己性格的哪种具体理解。","视觉呈现上，目前的像素颗粒感较强但略显粗糙，可以尝试优化边缘锯齿，或增加一些微妙的像素级光影变化，让牛皮纸纹理的质感更细腻。","既然设定为‘尘心自洽’，可以考虑在背景中加入极微小的、只有放大才能看清的像素细节（如飘落的尘埃或微小的音符），增加藏品的把玩趣味。"]', 'Qwen/Qwen3.5-397B-A17B', 'nft-forge-analysis-v1', '2026-08-02T13:37:51.344769', '2026-08-02T13:37:51.344784');

