INSERT INTO "nft_applications" ("id", "user_id", "name", "description", "theme", "public_attributes", "copyright_declaration", "image_data", "image_mime_type", "image_size_bytes", "image_width", "image_height", "status", "rejection_reason", "internal_review_note", "metadata_version_id", "collectible_token_type_id", "reviewed_by_user_id", "submitted_at", "reviewed_at", "created_at", "updated_at", "price_fan_tokens", "max_supply", "publish_fee_fan_tokens", "story_image_urls", "forge_session_id") VALUES ('a9ccd45a-2e70-4c1e-82e0-dd21a5953d15', '705c9595-ecc7-44cd-82fd-b3e6be27dd65', '粉圆·思绪漫游', '一枚粉色圆形徽章，以极简的黑色线条勾勒出闭目沉思的抽象面孔。周围环绕的波浪线条仿佛具象化的思绪或声波，在静谧中传递着内心的独白。', '演唱会纪念票根', '[{"trait_type":"主色调","value":"樱花粉"},{"trait_type":"艺术风格","value":"极简线条"},{"trait_type":"情绪状态","value":"内省沉思"},{"trait_type":"视觉元素","value":"抽象人脸"},{"trait_type":"构图形式","value":"圆形徽章"},{"trait_type":"票根类型","value":"典藏纪念"},{"trait_type":"质感","value":"手绘插画"},{"trait_type":"系列","value":"Fanora 情绪图腾"}]', '我确认拥有本次提交内容的发布权，并同意 Fanora 将其作为公开 NFT metadata 发布。', 'https://bee-mbr-ab.imglnk.cn/v/8f2fb8345c5aaccd29789e371ed4e0c3.jpg', 'image/jpeg', 79548, 1440, 1440, 'MINTED', NULL, NULL, 'd6d11f8b-79be-4f0a-a778-c9b2ae10f289', 'de062b55-909f-4005-a3bb-7c162e2d0ac5', NULL, '2026-08-02T09:49:43.957946+00:00', NULL, '2026-08-02T09:49:43.949434+00:00', '2026-08-02T09:49:43.949445+00:00', 20, 100, 100, '[]', '4f8ebfe4-eb45-43df-95ab-2642c3a21c96');
INSERT INTO "nft_applications" ("id", "user_id", "name", "description", "theme", "public_attributes", "copyright_declaration", "image_data", "image_mime_type", "image_size_bytes", "image_width", "image_height", "status", "rejection_reason", "internal_review_note", "metadata_version_id", "collectible_token_type_id", "reviewed_by_user_id", "submitted_at", "reviewed_at", "created_at", "updated_at", "price_fan_tokens", "max_supply", "publish_fee_fan_tokens", "story_image_urls", "forge_session_id") VALUES ('99abd959-53a5-4996-8306-c2da3aba3da4', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', '安可绽放时', '这是一枚凝固了演唱会最高潮瞬间的数字纪念票根。作品以横向悬浮的 3D 纸质票根为载体，左侧主画面将粉丝记忆中的镜像侧脸转化为温柔细腻的手绘插画：两抹背对背的剪影在舞台暖金逆光中静默伫立，象征着时间与自我的深情对话。缤纷的彩带如记忆碎片般在周身飞舞，与底部隐约的人群剪影交织，重现现场的热烈与感动。右侧保留经典的半圆缺口与虚线打孔副券，整体采用清新明亮的 pastel 色调与柔和投影，既是对那场梦境的温柔复刻，也是专属粉丝的情感资产，适合永久珍藏于数字钱包或作为社群身份徽章。', '演唱会纪念票根', '[{"trait_type":"收藏形态","value":"3D 悬浮票根"},{"trait_type":"视觉风格","value":"温柔手绘插画"},{"trait_type":"核心意象","value":"镜像侧脸与彩带"},{"trait_type":"光影氛围","value":"舞台暖金逆光"},{"trait_type":"情感基调","value":"怀旧庆典"},{"trait_type":"材质质感","value":"细腻纹理纸张"}]', '我确认拥有本次提交内容的发布权，并同意 Fanora 将其作为公开 NFT metadata 发布。', 'https://bee-mbr-ab.imglnk.cn/v/15f060eec3cbe3c9591ee7aab79d4151.png', 'image/png', 1475129, 1440, 720, 'MINTED', NULL, NULL, 'b2c87bc9-3319-4d14-b474-3d43676835b8', 'd3c65b42-29fb-4d7e-9b61-1c5c8a2b4919', NULL, '2026-08-02T12:10:25.520434+00:00', NULL, '2026-08-02T12:10:25.510879+00:00', '2026-08-02T12:10:25.510888+00:00', 20, 100, 100, '[]', 'e5790ba7-384d-43f7-94e1-2d0efcd14aab');
INSERT INTO "nft_applications" ("id", "user_id", "name", "description", "theme", "public_attributes", "copyright_declaration", "image_data", "image_mime_type", "image_size_bytes", "image_width", "image_height", "status", "rejection_reason", "internal_review_note", "metadata_version_id", "collectible_token_type_id", "reviewed_by_user_id", "submitted_at", "reviewed_at", "created_at", "updated_at", "price_fan_tokens", "max_supply", "publish_fee_fan_tokens", "story_image_urls", "forge_session_id") VALUES ('94c11f0e-3df0-4e40-b9e4-218f15de72f4', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', '写给这份喜欢的喜欢', '这份 NFT 记录的是：用户基于陈奕迅的视觉模板发起创作，提取了“成熟克制、略带疲惫、幽默内敛”的气质特征，以及“西装革履却略显忙乱、佩戴耳机”的视觉元素。创作核心从单纯的艺人肖像转化为一种普世的粉丝情感投射：在繁忙的成人世界（西装、便签、歪斜领带）中，依然通过音乐（耳机）守护内心秩序的普通人形象。视觉风格选定为 Chibi，旨在用柔和可爱的形式消解现实的沉重，强调“陪伴”与“自我和解”的情感价值。。它不补写未发生的演出、现场或共同经历，只保留粉丝亲自表达的欣赏与情绪。## 小标题', '陈奕迅', '[{"trait_type":"故事主角","value":"的形式消解"},{"trait_type":"情感","value":"欣赏与喜欢"}]', '我确认拥有本次提交内容的发布权，并同意 Fanora 将其作为公开 NFT metadata 发布。', 'https://bee-mbr-ab.imglnk.cn/v/1222b442fddddbdead26dd2363fc32df.png', 'image/png', 761483, 712, 1464, 'MINTED', NULL, NULL, '0d224e9b-8d39-429b-a8de-64c94ab7b885', '56ef9e83-1949-434a-9d20-781ee1e82c1e', NULL, '2026-08-02T12:22:56.871143+00:00', NULL, '2026-08-02T12:22:56.852698+00:00', '2026-08-02T12:22:56.852811+00:00', 20, 100, 100, '[]', 'edbbd798-6384-4540-8b49-8a330c74f5d1');
INSERT INTO "nft_applications" ("id", "user_id", "name", "description", "theme", "public_attributes", "copyright_declaration", "image_data", "image_mime_type", "image_size_bytes", "image_width", "image_height", "status", "rejection_reason", "internal_review_note", "metadata_version_id", "collectible_token_type_id", "reviewed_by_user_id", "submitted_at", "reviewed_at", "created_at", "updated_at", "price_fan_tokens", "max_supply", "publish_fee_fan_tokens", "story_image_urls", "forge_session_id") VALUES ('2707299e-36aa-4966-8f8f-25c91ed00bad', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', '霓虹情绪圆脸', '本作以手绘涂鸦为核心语言，将粉丝群体在音乐共鸣中瞬息万变的情绪具象化为数十个色彩斑斓的圆形面孔。作品摒弃具象场景，转而通过随性不完美的黑色线条与高饱和霓虹色块的层叠交错，构建出一种独立音乐周边的独特质感。Risograph 印刷特有的错位纹理与纸张颗粒感，赋予了数字藏品实体收藏的温度，寓意每一位听众都是这团黑色背景中不可或缺的独特光点，共同组成了这场永不散场的内心狂欢。', '周边形象', '[{"trait_type":"Visual Style","value":"Hand-drawn Doodle"},{"trait_type":"Texture","value":"Risograph Print"},{"trait_type":"Color Palette","value":"Neon 8-bit"},{"trait_type":"Composition","value":"Dense Overlap"},{"trait_type":"Vibe","value":"Whimsical Energy"},{"trait_type":"Collectible Type","value":"Indie Merch Art"}]', '我确认拥有本次提交内容的发布权，并同意 Fanora 将其作为公开 NFT metadata 发布。', 'https://bee-mbr-ab.imglnk.cn/v/8760c04111ee9b328679363431566ae5.png', 'image/png', 1355690, 1024, 1024, 'MINTED', NULL, NULL, '58ab9e09-6373-4dd6-ada6-f6d32361fe29', 'cb003d0d-c8fd-41fb-83cf-23bacdff1f05', NULL, '2026-08-02T12:27:13.117479+00:00', NULL, '2026-08-02T12:27:13.105539+00:00', '2026-08-02T12:27:13.105555+00:00', 3000, 50, 100, '[]', '38cef892-d02c-47d8-9906-2aa370087e44');
INSERT INTO "nft_applications" ("id", "user_id", "name", "description", "theme", "public_attributes", "copyright_declaration", "image_data", "image_mime_type", "image_size_bytes", "image_width", "image_height", "status", "rejection_reason", "internal_review_note", "metadata_version_id", "collectible_token_type_id", "reviewed_by_user_id", "submitted_at", "reviewed_at", "created_at", "updated_at", "price_fan_tokens", "max_supply", "publish_fee_fan_tokens", "story_image_urls", "forge_session_id") VALUES ('3ced625b-46ed-4968-80d1-2509afd65edd', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', '尘心自洽', '作品源自一段正在形成的真实粉丝记忆，以“尘大师”的意象隐喻自我和解的宁静时刻。画面重构为 8-bit 像素艺术风格，将原本手绘的冥想者转化为复古游戏中的治愈系角色。背景保留了旧牛皮纸的温暖棕色调与纤维质感，但通过像素网格重新诠释，营造出数字怀旧与手工温度交织的独特氛围。中央人物盘腿而坐，闭目微笑，夸张的卷发与简约衣着以明亮的色块呈现，既保留了原作的稚拙幽默，又增添了电子收藏品的趣味性与稀缺感。这不仅是一张专辑封面的数字变体，更是一枚象征内心平静与日常陪伴的像素徽章，记录着粉丝在音乐中找到共鸣的纯粹瞬间。', '尘大师', '[{"trait_type":"Style","value":"8-Bit Retro"},{"trait_type":"Mood","value":"Self-Reconciliation"},{"trait_type":"Texture","value":"Pixelated Kraft Paper"},{"trait_type":"Character State","value":"Meditating"},{"trait_type":"Rarity","value":"Fan Keepsake"},{"trait_type":"Color Palette","value":"Warm Earth Tones"}]', '我确认拥有本次提交内容的发布权，并同意 Fanora 将其作为公开 NFT metadata 发布。', 'https://bee-mbr-ab.imglnk.cn/v/733c9c2249024126416d99eac5bb1d42.png', 'image/png', 623164, 1024, 1024, 'MINTED', NULL, NULL, '29254f88-088e-4d22-9cd6-2893238ee769', '6a338765-af95-4c14-9f07-efc5f820b653', NULL, '2026-08-02T13:40:34.251395+00:00', NULL, '2026-08-02T13:40:34.240481+00:00', '2026-08-02T13:40:34.240494+00:00', 30, 500, 100, '[]', '47f73c72-a01c-4188-bd74-0ccee64d3eee');

