-- table: nft_visual_templates, rows: 10
INSERT INTO "nft_visual_templates" ("id", "owner_user_id", "source_post_id", "name", "category", "description", "prompt", "preview_image_url", "reference_image_urls", "palette", "elements", "forbidden", "is_system", "created_at", "updated_at") VALUES ('ab1fd158-979a-4ec1-8c55-7394d15406e5', '705c9595-ecc7-44cd-82fd-b3e6be27dd65', NULL, '周边形象', '音乐', 'playful hand-drawn doodle mascot characters, dozens of colorful circular faces with simple black line expressions, imperfect sketchy outlines, expressive minimal facial features, vibrant neon color palette, dense overlapping composition, sticker collection aesthetic, indie music merchandise illustration, risograph print texture, silkscreen printing, paper grain, Japanese pop graphic design, music festival souvenir artwork, energetic, whimsical, collectible art toy style, black background', 'playful hand-drawn doodle mascot characters, dozens of colorful circular faces with simple black line expressions, imperfect sketchy outlines, expressive minimal facial features, vibrant neon color palette, dense overlapping composition, sticker collection aesthetic, indie music merchandise illustration, risograph print texture, silkscreen printing, paper grain, Japanese pop graphic design, music festival souvenir artwork, energetic, whimsical, collectible art toy style, black background', 'https://gateway.pinata.cloud/ipfs/bafybeihgkfsd7ym5fzced66nuhgzjgys4rn4zo25wprmijqtq4h4rbp6lm', '["https://gateway.pinata.cloud/ipfs/bafybeihgkfsd7ym5fzced66nuhgzjgys4rn4zo25wprmijqtq4h4rbp6lm"]', '["#8B5CF6","#EC4899","#111827"]', '[]', '["Logo","水印","可读文字","未经授权的真实艺人肖像"]', TRUE, '2026-07-31T16:35:02.486151', '2026-07-31T16:35:02.486167');
INSERT INTO "nft_visual_templates" ("id", "owner_user_id", "source_post_id", "name", "category", "description", "prompt", "preview_image_url", "reference_image_urls", "palette", "elements", "forbidden", "is_system", "created_at", "updated_at") VALUES ('encore', NULL, NULL, '演唱会纪念票根', '音乐', 'Fear and Dearms演唱会的海报。超现实花卉双生人像演唱会纪念海报。', '超宽幅演唱会纪念海报，超现实梦境艺术风格，电影级视觉设计。

画面中央是参考图的两张巨大侧脸肖像，采用左右镜像、背对背的对称构图，两张脸分别望向画面左右两侧。人物闭眼或神情平静，表现回忆、梦想、时间和自我对话。

两张人物肖像的头部连接处爆发出一座繁盛的梦境花园，大量玫瑰、牡丹、雏菊、野花、绿叶和藤蔓从人物头发与思绪中生长出来。周围漂浮着彩色蝴蝶、花瓣、飞鸟、纸片、微小星光和象征记忆的碎片，部分元素向画面两侧扩散，产生动态感和空间层次。

背景是低饱和灰蓝色云层、柔和烟雾和朦胧天空，中央具有柔和逆光和银白色光晕。人物使用黑白或低饱和摄影质感，花朵使用鲜艳的红色、粉色、紫色、橙色和黄色，形成梦幻的冷暖色彩对比。

海报底部中央预留大型演唱会标题区域，标题文字厚重、洁白、略带立体浮雕和颗粒质感，花瓣与蝴蝶从文字前后穿过。顶部预留日期、城市、场馆、巡演名称和纪念信息。

华语大型演唱会主视觉，史诗感、梦境感、艺术摄影、精致数字拼贴、高级商业海报、丰富细节、宽银幕构图、印刷级画质。原创人物与原创构图，不复制任何现有演唱会海报。', 'https://bee-mbr-ab.imglnk.cn/v/bdd55bd25050f6ba3dd692b710c2f426.webp', '["https://bee-mbr-ab.imglnk.cn/v/bdd55bd25050f6ba3dd692b710c2f426.webp"]', '["#FB7185","#A855F7","#312E81"]', '["安可彩带","逆光舞台","人群剪影"]', '["艺人真实肖像","Logo","水印","可读文字"]', TRUE, '2026-07-31T14:45:05.476900', '2026-08-02T07:42:23.600503');
INSERT INTO "nft_visual_templates" ("id", "owner_user_id", "source_post_id", "name", "category", "description", "prompt", "preview_image_url", "reference_image_urls", "palette", "elements", "forbidden", "is_system", "created_at", "updated_at") VALUES ('e0402c7e-4ba5-4b58-88d7-97bcf43ab80d', '705c9595-ecc7-44cd-82fd-b3e6be27dd65', NULL, 'chin up', '专辑', '一张纵向艺术唱片封面，采用粗粝的手绘拼贴风格。画面以高饱和钴蓝色为主背景，加入横向醒目的红色色带和右侧多彩竖条，形成强烈的平面构成。中央放置一个夸张、略带荒诞感的主体，可以是人物、动物、玩偶或抽象物体，采用黑色炭笔线稿、蜡笔涂抹、油画棒和旧纸拼贴表现。', '纵向艺术唱片封面，原创手绘拼贴插画，高饱和钴蓝色背景，横向鲜红色几何色带，右侧排列多条彩色竖直色块，中央是一个夸张而荒诞的[主体]，主体姿态略微倾斜并向上延伸，具有幽默、笨拙、乐观、充满生命力的感觉。
使用黑色炭笔线稿、蜡笔、油画棒、粗糙水彩和旧纸拼贴质感，轮廓不规则，线条带有手绘抖动感，局部色彩溢出，纸张边缘撕裂，保留印刷错位、刮擦、磨损和手工涂改痕迹。
画面加入几张漂浮或贴在背景上的白色撕纸标签，上面预留简洁的主题文字区域，例如“[主题词]”“[副标题]”，文字采用粗黑色手写字体。构图大胆、平面化、具有现代艺术海报感，留出清晰的视觉焦点，色彩强烈但富有童趣。
原创作品，不复制任何现有专辑封面，不使用真实歌手肖像，不复刻已有文字排版。', 'https://bee-mbr-ab.imglnk.cn/v/8dec1821ab1647b451e2db4b84ffa17f.jpg', '["https://bee-mbr-ab.imglnk.cn/v/8dec1821ab1647b451e2db4b84ffa17f.jpg"]', '["#8B5CF6","#EC4899","#111827"]', '[]', '["Logo","水印","可读文字","未经授权的真实艺人肖像"]', TRUE, '2026-08-02T08:15:08.063731', '2026-08-02T08:15:08.063745');
INSERT INTO "nft_visual_templates" ("id", "owner_user_id", "source_post_id", "name", "category", "description", "prompt", "preview_image_url", "reference_image_urls", "palette", "elements", "forbidden", "is_system", "created_at", "updated_at") VALUES ('cf106c6a-ce31-4e98-9a14-ec23f3572420', '705c9595-ecc7-44cd-82fd-b3e6be27dd65', NULL, '演唱会周边', '粉丝周边', '一幅极简、童趣的手绘头像插画。', '极简儿童涂鸦风插画，纯白背景，画面中央放置一个巨大的荧光绿色正圆形，圆形几乎填满整个正方形画布。圆形内部用粗厚、圆润、略微不规则的纯黑色手绘线条表现一张正面的忧郁小老虎脸：两道向内倾斜的弯眉，豆状黑眼睛，小巧抽象的鼻子，明显向下弯曲的嘴巴，神情委屈又可爱。脸部边缘及额头均匀分布黑色短弧线和块状虎纹。扁平矢量图形，手绘简笔画，幼稚感，潮流贴纸设计，表情包风格，无阴影，无渐变，无纹理，高饱和荧光绿与纯黑强烈对比，居中构图，干净留白，1:1。', 'https://bee-mbr-ab.imglnk.cn/v/9f9da1c146c53df04a761b98a7186adf.jpg', '["https://bee-mbr-ab.imglnk.cn/v/9f9da1c146c53df04a761b98a7186adf.jpg"]', '["#8B5CF6","#EC4899","#111827"]', '[]', '["Logo","水印","可读文字","未经授权的真实艺人肖像"]', TRUE, '2026-08-02T08:59:41.648636', '2026-08-02T08:59:41.648660');
INSERT INTO "nft_visual_templates" ("id", "owner_user_id", "source_post_id", "name", "category", "description", "prompt", "preview_image_url", "reference_image_urls", "palette", "elements", "forbidden", "is_system", "created_at", "updated_at") VALUES ('358b4ff2-2b38-4830-8d96-06b4b69bdbc8', '705c9595-ecc7-44cd-82fd-b3e6be27dd65', NULL, 'H3M', '专辑', '是一位[人物身份]的黑白或低饱和肖像，人物采用三分之二侧身构图，肩膀略微转向镜头，眼神平静而直接。使用柔和侧光，突出发丝、面部轮廓、胡须和服装质感。背景完全干净，没有复杂装饰，整体呈现安静、成熟、冷静、优雅的音乐专辑气质。', '方形音乐专辑封面设计，极简高级风格，温暖象牙白背景，大面积留白。

画面上方是一个大型复古高对比衬线字体字标，字母相互叠压、穿插、局部重叠，具有古典唱片和高级时装品牌的气质，下方排列小号艺术家名称。

画面下半部分是一位[人物身份]的半身肖像，三分之二侧身面对镜头，头部轻微转向，眼神平静、深沉、自信。人物穿着[服装描述]，发型[发型描述]，面部具有清晰轮廓和成熟气质。

黑白摄影，低饱和灰绿色调，柔和侧光，细腻阴影，突出发丝、皮肤、胡须和衣料纹理。整体感觉安静、克制、优雅、成熟、富有音乐性，像一张高端华语流行音乐专辑封面。

右下角加入一个很小的极简方形唱片公司标志区域。留白充足，构图平衡，印刷品质感，真实摄影与平面设计结合。

原创人物和原创文字排版，不复制现有专辑封面，不使用真实歌手肖像。', 'https://bee-mbr-ab.imglnk.cn/v/0fa37ed2d125e178edf9ce2cc58abc4b.jpg', '["https://bee-mbr-ab.imglnk.cn/v/0fa37ed2d125e178edf9ce2cc58abc4b.jpg"]', '["#8B5CF6","#EC4899","#111827"]', '[]', '["Logo","水印","可读文字","未经授权的真实艺人肖像"]', TRUE, '2026-08-02T08:21:39.501701', '2026-08-02T08:21:39.501715');
INSERT INTO "nft_visual_templates" ("id", "owner_user_id", "source_post_id", "name", "category", "description", "prompt", "preview_image_url", "reference_image_urls", "palette", "elements", "forbidden", "is_system", "created_at", "updated_at") VALUES ('f3f1d92b-b2c5-4b78-8edd-024336a3b343', '705c9595-ecc7-44cd-82fd-b3e6be27dd65', NULL, '陈奕迅', '粉丝周边', '陈奕迅，脸型偏长，额头开阔，柔和的下颌线，内双眼睛，平直自然的眉毛，沉静温和的眼神，鼻梁适中，薄嘴唇，面部保留真实年龄感和轻微疲惫感；黑色短发，两侧较短，顶部蓬松凌乱并向上翘起；成熟、幽默、克制、略带忧郁的华语男歌手气质。', '陈奕迅，香港中年男性歌手形象，正面半身肖像，脸型偏长而柔和，额头开阔，颧骨与下颌轮廓自然，单眼皮或内双，眼神沉静温和，眉毛自然平直，鼻梁适中，嘴唇较薄，嘴角轻微下垂，面部保留真实皮肤纹理，成熟、克制、略带疲惫感。

黑色短发，顶部蓬松凌乱，发梢向上翘起，两侧较短。身穿浅灰色细格纹西装、浅蓝色衬衫和酒红色斜纹领带，领口略微松开，领带自然歪斜。西装口袋和胸前夹着黄色便签本、证件卡、钢笔与蓝色小物件，呈现略显忙乱的办公室职员造型。双耳佩戴黑色舞台入耳式耳机。

人物正面站立，稍微仰头，平静地看向镜头，表情严肃但不冷漠。深灰黑色纯色背景，柔和正面光，真实摄影，纪录片式人物肖像，低饱和色彩，细腻皮肤质感，自然比例，竖版构图。', 'https://bee-mbr-ab.imglnk.cn/v/80ae45426f64eba73cc29cca90491445.jpg', '["https://bee-mbr-ab.imglnk.cn/v/80ae45426f64eba73cc29cca90491445.jpg"]', '["#8B5CF6","#EC4899","#111827"]', '[]', '["Logo","水印","可读文字","未经授权的真实艺人肖像"]', TRUE, '2026-08-02T08:31:50.911896', '2026-08-02T08:31:50.911930');
INSERT INTO "nft_visual_templates" ("id", "owner_user_id", "source_post_id", "name", "category", "description", "prompt", "preview_image_url", "reference_image_urls", "palette", "elements", "forbidden", "is_system", "created_at", "updated_at") VALUES ('ac15fbbb-33e6-461c-ba4e-639aaf1203b6', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', NULL, '史诗eason', '专辑', '自动生成一张收藏版史诗叙事海报', '巨大的陈奕迅侧脸剪影作为外轮廓，剪影内部自动生长出最契合该主题的完整世界观、标志性场景、角色关系、象征符号、关键建筑、生物、道具与氛围。整体不是普通拼贴，而是高级的剪影轮廓填充式叙事合成，带有双重曝光式联想，但更偏电影海报与梦幻水彩插画融合风格；柔和空气透视，轻雾化过渡，纸张颗粒，边缘飞白与刷痕，大面积留白，版式克制高级，安静、宏大、神圣、怀旧、诗意、传说感。风格、色彩、场景、材质全部根据主题自动适配，所有元素必须强绑定主题，一眼识别，不要杂乱，不要硬拼贴，不要模板化背景，不要廉价奇幻素材。', 'https://bee-mbr-ab.imglnk.cn/v/b0b049b18fac1d6ca8417d5121e5d1e1.jpg', '["https://bee-mbr-ab.imglnk.cn/v/b0b049b18fac1d6ca8417d5121e5d1e1.jpg"]', '["#8B5CF6","#EC4899","#111827"]', '[]', '["Logo","水印","可读文字","未经授权的真实艺人肖像"]', TRUE, '2026-08-02T12:35:38.143010', '2026-08-02T12:35:38.143028');
INSERT INTO "nft_visual_templates" ("id", "owner_user_id", "source_post_id", "name", "category", "description", "prompt", "preview_image_url", "reference_image_urls", "palette", "elements", "forbidden", "is_system", "created_at", "updated_at") VALUES ('49a46452-507d-4083-b07d-285e42509b27', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', NULL, '尘大师', '粉丝周边', '方形音乐专辑封面，极简手绘插画，朴素禅意风格。', '背景是一张旧棕色牛皮纸，纸张有明显的褶皱、折痕、纤维纹理、自然阴影和手工纸张质感。画面中央是一位原创男性卡通人物，盘腿坐着，双手自然放在膝盖上，闭着眼睛，脸上带着平静而温和的微笑，表现冥想、放松、沉思和自我和解。

人物使用非常简洁的黑色手绘线条勾勒，线条粗细不均、略微抖动，具有儿童画和手账插画的稚拙感。人物有夸张的黑色卷发，穿着简单的棕色或米色长袖上衣和裤子，胸前有极简黑色领口细节。

人物上方预留几行粗黑色手写中文书法标题区域，字迹自然、潦草、有墨水晕染感。人物下方预留小号手写英文艺术家名称区域。构图居中，大面积留白，温暖棕色调，黑色线稿与纸张背景形成强烈对比。

整体感觉安静、幽默、质朴、治愈、略带哲思，像一张独立音乐专辑、手工限量唱片封面或私人日记插画。原创人物和原创文字排版，不复制现有专辑封面。', 'https://bee-mbr-ab.imglnk.cn/v/e59f0a24a3df1a6014b28f60279b5624.jpg', '["https://bee-mbr-ab.imglnk.cn/v/e59f0a24a3df1a6014b28f60279b5624.jpg"]', '["#8B5CF6","#EC4899","#111827"]', '[]', '["Logo","水印","可读文字","未经授权的真实艺人肖像"]', TRUE, '2026-08-02T12:37:01.107853', '2026-08-02T12:37:01.107859');
INSERT INTO "nft_visual_templates" ("id", "owner_user_id", "source_post_id", "name", "category", "description", "prompt", "preview_image_url", "reference_image_urls", "palette", "elements", "forbidden", "is_system", "created_at", "updated_at") VALUES ('38c732ea-569d-41ca-b7de-7db4648e0e49', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', NULL, '信心花舍', '粉丝周边', '原创 Q 版卡通人物插画，纯白色背景，画面中央一个圆润可爱的卡通男孩。', '原创 Q 版卡通人物插画，纯白色背景，画面中央一个圆润可爱的卡通男孩。

人物拥有蓬松凌乱的黑色短发，头发轮廓柔软，有几撮自然翘起的发梢。脸型圆润，肤色为柔和的浅蜜桃色，五官极简：两颗小黑点眼睛、粗短黑色眉毛、简化的小嘴巴。人物双手托着脸颊，手肘放在前方，表情害羞、困倦又有一点撒娇感，脸颊带有明显的粉红色腮红和几条竖向 blush 线。

人物穿着黑色外套或黑色西装，内搭白色衬衫和小圆领，坐在鲜艳的玫红色软椅或圆形坐垫上。头顶悬浮一个不规则、略微倾斜的粉红色光环，线条像霓虹灯管，带有柔和的洋红色发光效果。

使用圆润柔和的手绘线条，简单平涂色块，轻微纸张颗粒，边缘略带手绘不规则感。色彩以黑色、白色、浅肤色和鲜艳玫红色为主，视觉干净，角色居中，留白充足，甜美、害羞、俏皮、治愈，适合头像、贴纸、表情包和粉丝周边设计。', 'https://bee-mbr-ab.imglnk.cn/v/c4b83d11633939b0dd5cc37195a1be5e.jpg', '["https://bee-mbr-ab.imglnk.cn/v/c4b83d11633939b0dd5cc37195a1be5e.jpg"]', '["#8B5CF6","#EC4899","#111827"]', '[]', '["Logo","水印","可读文字","未经授权的真实艺人肖像"]', TRUE, '2026-08-02T12:38:33.838509', '2026-08-02T12:38:33.838532');
INSERT INTO "nft_visual_templates" ("id", "owner_user_id", "source_post_id", "name", "category", "description", "prompt", "preview_image_url", "reference_image_urls", "palette", "elements", "forbidden", "is_system", "created_at", "updated_at") VALUES ('33ec1d82-f9b1-4482-82a1-f1a8ef41904c', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', NULL, 'K 歌之王', '专辑', '方形音乐专辑封面，极简电影感摄影设计，上下分割的双重肖像构图。', '上半部分是深墨绿色近黑色背景，一位成熟男性的侧脸近距离特写，人物低头闭眼，神情安静、疲惫、内省。脸部大部分隐藏在黑色阴影中，只保留鼻梁、嘴唇、脸颊和凌乱发丝上的温暖棕色轮廓光。画面具有低调、克制、孤独的气氛。

下半部分是橙色、焦糖色和浅杏色组成的柔和渐变背景，同一人物以几乎纯黑的侧身剪影出现，头部向下倾斜，肩膀和发型轮廓清晰，边缘有非常微弱的暖色逆光。上下两个肖像形成情绪上的镜像关系，象征自我对话、沉默、记忆和舞台之后的孤独。

中央横跨上下色块分界线，预留纤细、宽字距、现代无衬线白色标题文字区域。左侧预留小号艺术家名称。构图平衡，大面积留白，强烈明暗对比，低饱和暗色摄影与暖橙色渐变结合，独立音乐专辑封面，高级平面设计，细腻胶片颗粒，安静、成熟、忧郁、诗意。

原创人物与原创排版，不复制现有专辑封面，不使用真实歌手肖像。', 'https://bee-mbr-ab.imglnk.cn/v/d3487e747d978510ec908ef8638f4d3b.jpg', '["https://bee-mbr-ab.imglnk.cn/v/d3487e747d978510ec908ef8638f4d3b.jpg"]', '["#8B5CF6","#EC4899","#111827"]', '[]', '["Logo","水印","可读文字","未经授权的真实艺人肖像"]', TRUE, '2026-08-02T12:33:25.468019', '2026-08-02T12:33:25.468037');

