INSERT INTO "task_participations" ("id", "task_id", "user_id", "status", "reward_snapshot", "reply_id", "claimed_at", "submitted_at", "completed_at", "submission") VALUES ('0eeb3452-42ca-4ded-9faf-07f07ec41ab5', '00000000-0000-0000-0000-000000000020', '705c9595-ecc7-44cd-82fd-b3e6be27dd65', 'rewarded', 500, NULL, '2026-07-20T15:44:41.986526+00:00', '2026-07-23T08:37:50.317896+00:00', '2026-07-23T08:37:50.317896+00:00', '{"body":"8.11 澳门尾场安可九，竟然唱到了第二天，幸福晕了🥰感谢乐队老师，浮夸！！！我还没有从武汉走出来，我又困在澳门了😭谁说我的老爱豆唱不上去的！！！无敌舞美，无敌 Live！！","image_urls":["https://bee-mbr-ab.imglnk.cn/v/c95d4ad80d3aaae7752885c2705b55bf.jpg"]}');
