INSERT INTO "task_participations" ("id", "task_id", "user_id", "status", "reward_snapshot", "reply_id", "claimed_at", "submitted_at", "completed_at", "submission") VALUES ('7215e91c-740b-4476-a702-651d7a709105', '00000000-0000-0000-0000-000000000005', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', 'rewarded', 80, '22244154-1d78-4e46-836a-e51d36a9237f', '2026-07-24T09:20:01.122408+00:00', '2026-07-24T09:20:23.138758+00:00', '2026-07-24T09:20:23.138758+00:00', '{}');
INSERT INTO "task_participations" ("id", "task_id", "user_id", "status", "reward_snapshot", "reply_id", "claimed_at", "submitted_at", "completed_at", "submission") VALUES ('f15c0c44-cd7a-4a99-a35d-640b551bede1', '00000000-0000-0000-0000-000000000020', '1385e9a6-dcec-4db0-a8cf-8302c9542f03', 'rewarded', 500, NULL, '2026-07-23T11:01:28.718433+00:00', '2026-07-23T11:07:06.489720+00:00', '2026-07-23T11:07:06.489720+00:00', '{"body":"FEAR and DREAMS · 现场瞬间\n\n那一晚《FEAR and DREAMS》的灯光熄灭时，全场突然安静下来，只剩下观众席此起彼伏的荧光点。我原本以为自己只是来听一场演唱会，但当陈奕迅唱到那句熟悉的歌词时，身边陌生人也跟着一起轻声合唱，我第一次真正感受到“几万人同时拥有同一种情绪”是什么样子。\n\n我记得最深的是副歌响起的瞬间，舞台的大屏从冷色调慢慢切换成温暖的光，整个体育馆像被一层记忆包裹住。那一刻我没有举手机录像，而是把手里的灯牌举高，认真地看完了整首歌。后来回想起来，我甚至记不清具体坐在哪一排，却能清楚记得当时胸口那种被音乐击中的感觉。\n\n很多人说演唱会结束后只剩散场的人潮，但《","image_urls":["https://bee-mbr-ab.imglnk.cn/v/a281c40ae32337f221d67a462f51f170.jpg"]}');
INSERT INTO "task_participations" ("id", "task_id", "user_id", "status", "reward_snapshot", "reply_id", "claimed_at", "submitted_at", "completed_at", "submission") VALUES ('23affc27-456c-4ffd-921e-6a50862696a3', '00000000-0000-0000-0000-000000000020', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', 'rewarded', 500, NULL, '2026-07-24T09:17:27.177199+00:00', '2026-07-24T09:18:10.959605+00:00', '2026-07-24T09:18:10.959605+00:00', '{"body":"FEAR and DREAMS｜把一次现场相遇，变成一辈子的记忆\n\n第一次走进 FEAR and DREAMS 演唱会现场时，我以为自己只是来听一场演唱会。\n\n直到灯光熄灭，音乐响起，全场数万人的欢呼汇聚成同一种心跳，我才发现，这不是一场普通的演出，而是一场关于成长、勇气和梦想的旅程。\n\n陈奕迅没有刻意煽情，却总能用一首歌唱出每个人心里的故事。\n\n当熟悉的旋律响起，身边素不相识的人一起合唱，手机灯光像星海一样铺满整个场馆。那一刻，我们来自不同的城市，有着不同的人生，却因为同一个声音，相遇在同一个夜晚。\n\n《FEAR and DREAMS》让我明白，恐惧从来不会消失，但梦想会给人继续前行的勇气。","image_urls":["https://bee-mbr-ab.imglnk.cn/v/4726af85e3122fa609374669105213b7.jpg"]}');

