INSERT INTO "task_audit_logs" ("id", "task_id", "participation_id", "actor_user_id", "event", "from_status", "to_status", "detail", "created_at") VALUES ('95cbefbf-8747-46d1-a809-449b5daa08f2', '00000000-0000-0000-0000-000000000020', '23affc27-456c-4ffd-921e-6a50862696a3', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', 'claimed', NULL, 'claimed', NULL, '2026-07-24T09:17:27.179273+00:00');
INSERT INTO "task_audit_logs" ("id", "task_id", "participation_id", "actor_user_id", "event", "from_status", "to_status", "detail", "created_at") VALUES ('da1539be-92fe-49f1-bb9c-918f151d44ed', '00000000-0000-0000-0000-000000000020', '23affc27-456c-4ffd-921e-6a50862696a3', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', 'verified_and_rewarded', 'claimed', 'rewarded', 'Event-page memory: FEAR and DREAMS｜把一次现场相遇，变成一辈子的记忆

第一次走进 FEAR and DREAMS 演唱会现场时，我以为自己只是来听一场演唱会。

直到灯光熄灭，音乐响起，全场数万人的欢呼汇聚成同一种心跳，我才发现，这不是一场普通的演出，而是一场关于成长、勇气和梦想的旅程。

陈奕迅没有刻意煽情，却总能用一首歌唱出每个人心里的故事。

当熟悉的旋律响起，身边素不相识的人一起合唱，手机灯光像星海一样铺满整个场馆。那一刻，我们来自不同的城市，有着不同的人生，却因为同一个声音，相遇在同一个夜晚。

《FEAR and DREAMS》让我明白，恐惧从来不会消失，但梦想会给人继续前行的勇气。', '2026-07-24T09:18:27.380715+00:00');
